const t=[{id:"l.st-columns.kink",xp:30,title:{en:"Raise P_u until P_u/φP_nx reaches 0.2: LS₁ switches to its 8/9 branch",ar:"زوّد P_u لحد ما P_u/φP_nx توصل 0.2: LS₁ بتقلب على فرع الـ 8/9"},check:e=>e.mode==="beamcol"&&e.bcHigh},{id:"l.st-columns.ls1",xp:30,title:{en:"Hold the column with a strut until LS₁ governs instead of LS₂",ar:"امسك العمود بستراتة لحد ما LS₁ هي اللي تحكم بدل LS₂"},check:e=>e.mode==="beamcol"&&e.bcBrace==="strut"&&e.bcGov==="LS1"},{id:"l.st-columns.light",xp:40,title:{en:"Find a lighter IPE than the IPE 400 that still passes both limit states",ar:"لاقي IPE أخف من IPE 400 ولسه بيعدّي الحالتين الحديتين"},check:e=>e.mode==="beamcol"&&e.bcOk&&["IPE360","IPE330","IPE300","IPE270"].includes(e.bcSec)}],a=[{id:"l.st-columns.b2",xp:30,title:{en:"Add gravity on the leaning columns until B₂ passes 2 — and watch the check fail",ar:"زوّد الأحمال على الأعمدة المستندة لحد ما B₂ تعدّي 2 — وشوف المراجعة بتقع"},check:e=>e.mode==="beamcol"&&e.bcB2>2},{id:"l.st-columns.unstable",xp:40,title:{en:"Push ΣP_u/ΣP_e2 to 1: the frame buckles sideways under gravity alone",ar:"وصّل ΣP_u/ΣP_e2 لـ 1: الإطار بينبعج جانبيًا تحت الجاذبية لوحدها"},check:e=>e.mode==="beamcol"&&e.bcUnstable},{id:"l.st-columns.tie",xp:30,title:{en:"Tie the frame (sway prevented): B₂ disappears and only B₁ is left",ar:"اربط الإطار بشداد (الحركة ممنوعة): B₂ بتختفي ويفضل B₁ بس"},check:e=>e.mode==="beamcol"&&e.bcFrame==="tied"}],n=[{id:"l.st-columns.cb1",xp:30,title:{en:"Find the frame whose column has Cb = 1.0",ar:"لاقي الإطار اللي عموده Cb = 1.0"},check:e=>e.mode==="beamcol"&&e.bcCb<=1.0001},{id:"l.st-columns.cm06",xp:30,title:{en:"Find the frame whose column gets Cm = 0.6",ar:"لاقي الإطار اللي عموده بياخد Cm = 0.6"},check:e=>e.mode==="beamcol"&&Math.abs(e.bcCm-.6)<1e-6},{id:"l.st-columns.curved",xp:30,title:{en:"Switch the Fink column to the curved wind diagram and read Cb from the quarter points",ar:"حوّل عمود فينك لمنحنى الرياح المنحني واقرا Cb من نقط الأرباع"},check:e=>e.mode==="beamcol"&&e.bcFrame==="fink"&&e.bcDiagram==="wind"}],s=[{id:"l.st-columns.knee",xp:30,title:{en:"Add knee braces: L_u halves but L_b,out does not",ar:"ركّب ركب (Knee braces): L_u بيتقسم نصين و L_b,out لأ"},check:e=>e.mode==="beamcol"&&e.bcBrace==="knee"},{id:"l.st-columns.strut",xp:40,title:{en:"Make the column pass with a strut in the vertical bracing",ar:"خلّي العمود يعدّي بستراتة في الشكالات الرأسية"},check:e=>e.mode==="beamcol"&&e.bcBrace==="strut"&&e.bcOk},{id:"l.st-columns.plastic",xp:40,title:{en:"Bring the unbraced length below L_p: the plastic plateau of the LTB curve",ar:"نزّل الطول غير المثبت تحت L_p: الجزء اللدن من منحنى الانبعاج الجانبي"},check:e=>e.mode==="beamcol"&&e.bcZone==="plastic"}],o=[{id:"l.st-columns.ipe400",xp:30,title:{en:"Try the pre-sized IPE 400: LS₂ fails",ar:"جرّب الـ IPE 400 بتاع أول مقاس: LS₂ بتقع"},check:e=>e.mode==="beamcol"&&e.bcSec==="IPE400"&&e.bcLS2>1},{id:"l.st-columns.heb220",xp:30,title:{en:"Try HEB 220: it fails too, so HEB 240 is the lightest HEB",ar:"جرّب HEB 220: هو كمان بيقع، يبقى HEB 240 هو أخف HEB"},check:e=>e.mode==="beamcol"&&e.bcSec==="HEB220"&&!e.bcOk}],$=[{id:"l.st-columns.ws-free",xp:30,title:{en:"Take away the crane-girder support: L_b,out and L_u become 6 m — the HEB 300 still passes",ar:"شيل سند كمرة الونش: L_b,out و L_u بيبقوا 6 م — والـ HEB 300 لسه بيعدّي"},check:e=>e.mode==="beamcol"&&e.bcFrame==="fink"&&e.bcBrace==="none"&&e.bcOk},{id:"l.st-columns.ws-ipe",xp:40,title:{en:"Try the IPE 270 of the pre-sizing for the roof and the wind alone",ar:"جرّب الـ IPE 270 بتاع أول مقاس للسقف والرياح لوحدهم"},check:e=>e.mode==="beamcol"&&e.bcSec==="IPE270"&&e.bcOk}],i={sections:[{id:"nm",title:{en:"Normal force only, or normal force and moment?",ar:"قوة عمودية بس، ولا قوة عمودية وعزم؟"},blocks:[{t:"p",text:{en:"A column whose loads arrive exactly on its axis, through connections that cannot pass a moment, carries **N only** — an interior column of a braced building with beams on shear connections on both sides and equal spans, a strut of the bracing, a truss member. Most columns of a shed are not like that: they carry **N + M** and are called **beam-columns**. The moment comes from:",ar:"العمود اللي أحماله بتيجي على محوره بالظبط، عن طريق وصلات مش بتنقل عزم، بيشيل **N بس** — عمود داخلي في مبنى متربط عليه كمرات بوصلات قص من الناحيتين وبحور متساوية، أو ستراتة في الشكالات، أو عضو في جمالون. أغلب أعمدة الهنجر مش كده: بتشيل **N + M** واسمها **أعمدة تحت حمل وعزم (Beam-columns)**. العزم بييجي من:"}},{t:"steps",items:[{en:"**The frame action**: a portal frame with rigid knees, or a truss connected to the column at both its chords, makes the column part of a frame — the wind sways it and bends it.",ar:"**شغل الإطار**: إطار بوابي أركانه جاسئة، أو جمالون متوصل في العمود عند الوترين، بيخلّي العمود جزء من إطار — الرياح بتحرّكه جانبيًا وبتحنيه."},{en:"**The wind on the wall**: the side girts hand the wall pressure to the column as a load along its height — even a column under a truss pinned on top becomes a cantilever in bending.",ar:"**الرياح على الحائط**: المدادات الجانبية بتسلّم ضغط الحائط للعمود كحمل على طول ارتفاعه — حتى العمود اللي عليه جمالون مفصلي من فوق بيبقى كابولي بينحني."},{en:"**Eccentric loads**: a crane girder or a mezzanine beam on a bracket at a distance e from the axis gives M = R·e; a cantilever (canopy) truss gives the column its whole overturning moment.",ar:"**الأحمال اللامركزية**: كمرة ونش أو كمرة ميزانين على كابولي على بعد e من المحور بتدّي M = R·e؛ والجمالون الكابولي (المظلة) بيدّي العمود عزم الانقلاب كله."}]},{t:"p",text:{en:"For a beam-column the two effects meet: the normal force wants the column to buckle, the moment bends it — and the bending adds to the buckling, because the bent column carries its normal force with a lever arm. The checks of this lesson (the interaction of the two, the amplification, the moment factors, lateral–torsional buckling, the class of the section under N + M) all come from that.",ar:"في العمود اللي تحت حمل وعزم التأثيرين بيتقابلوا: القوة العمودية عايزة العمود ينبعج، والعزم بيحنيه — والانحناء بيزوّد الانبعاج، لأن العمود المنحني بيشيل قوته العمودية بذراع. كل مراجعات الدرس ده (التفاعل بين الاتنين، والتكبير، ومعاملات العزم، والانبعاج الجانبي الالتوائي، وتصنيف القطاع تحت N + M) طالعة من كده."}},{t:"quiz",q:{kind:"mcq",q:{en:"Which of these columns carries a normal force only?",ar:"أنهي عمود من دول بيشيل قوة عمودية بس؟"},options:[{en:"an interior column of a braced building, with beams on shear connections on both sides and equal spans",ar:"عمود داخلي في مبنى متربط، عليه كمرات بوصلات قص من الناحيتين وبحور متساوية"},{en:"the side column of a trussed frame connected at both chords",ar:"العمود الطرفي لإطار بجمالون متوصل عند الوترين"},{en:"a column carrying a crane girder on a bracket",ar:"عمود شايل كمرة ونش على كابولي"}],answer:0,explain:{en:"Equal reactions on both sides through connections that pass no moment: the load stays on the axis. The other two are bent by the frame action and by the bracket.",ar:"ردود أفعال متساوية من الناحيتين بوصلات مش بتنقل عزم: الحمل بيفضل على المحور. والاتنين التانيين بينحنوا من شغل الإطار ومن الكابولي."}}}]},{id:"section",title:{en:"Choosing the section and naming its axes",ar:"اختيار القطاع وأسماء محاوره"},blocks:[{t:"table",head:[{en:"Situation",ar:"الحالة"},{en:"Section",ar:"القطاع"}],rows:[[{en:"moment in the plane of the frame only, L_b,out < 7 m",ar:"عزم في مستوى الإطار بس، و L_b,out أقل من 7 م"},"IPE"],[{en:"a moment out of plane as well, or L_b,out > 7 m",ar:"فيه عزم خارج المستوى كمان، أو L_b,out أكبر من 7 م"},"HEB"],[{en:"heavy loads on a tall column (crane columns): a large in-plane moment and normal force, L_b,out beyond about 7–8 m, any out-of-plane moment smaller than the in-plane one",ar:"أحمال تقيلة على عمود عالي (أعمدة الأوناش): عزم داخل المستوى وقوة عمودية كبار، و L_b,out أكبر من حوالي 7–8 م، وأي عزم خارج المستوى أصغر من اللي جوّه"},{en:"built-up: 2 channels, 2 IPE or 4 angles in a rectangle, with lacing or battens",ar:"مركب: 2 مجرى أو 2 IPE أو 4 زوايا في مستطيل، بأسياخ أو ألواح ربط"}],[{en:"large moments in both planes, about equal, or L_b,out far beyond 7–8 m",ar:"عزوم كبيرة في المستويين وقريبة من بعض، أو L_b,out أكبر بكتير من 7–8 م"},{en:"built-up, stiff both ways: 2 crossed I-sections or 4 angles in a square",ar:"مركب جاسئ في الاتجاهين: 2 قطاع I متعامدين أو 4 زوايا في مربع"}]],caption:{en:"An IPE is deep and narrow: stiff in the frame plane, weak out of it, where the wall bracing must hold it. An HEB has a radius r_y about twice as large. A single IPE is kept up to an out-of-plane length of about 7 m and an HEB takes over beyond it; under heavy loads, beyond 7–8 m, two chords set far apart give the out-of-plane radius a long length needs (the built-up columns lesson designs them).",ar:"الـ IPE عميق وضيق: جاسئ في مستوى الإطار وضعيف خارجه، وهناك شكالات الحائط لازم تمسكه. والـ HEB نصف قطر القصور r_y بتاعه حوالي الضعف. الـ IPE الواحد بيمشي لحد طول خارج المستوى حوالي 7 م وبعده الـ HEB بياخد مكانه؛ ومع الأحمال التقيلة، بعد 7–8 م، فرعين بعاد عن بعض بيدّوا نصف قطر القصور خارج المستوى اللي الطول الكبير محتاجه (درس الأعمدة المركبة بيصممهم)."}},{t:"p",text:{en:"**Axis names.** A rolled column stands with its web in the plane of the frame: it bends in plane about its strong axis x, so $M_{in} = M_x$ and $M_{out} = M_y$. A **built-up** column of two chords bends in plane about the axis **between** the chords, which is called y: $M_{in} = M_y$ and $M_{out} = M_x$. Same frame, the letters swap — read the axis before you read the formula.",ar:"**أسماء المحاور.** العمود المدرفل بيتركب وعصبه في مستوى الإطار: بينحني داخل المستوى حوالين محوره القوي x، يبقى $M_{in} = M_x$ و $M_{out} = M_y$. أما العمود **المركب** من فرعين فبينحني داخل المستوى حوالين المحور اللي **بين** الفرعين، واسمه y: يبقى $M_{in} = M_y$ و $M_{out} = M_x$. نفس الإطار والحروف بتتبدل — اقرا المحور قبل ما تقرا المعادلة."}},{t:"eq",tex:"S_x = \\dfrac{M_{ux}}{(0.7\\ldots0.9)\\,\\phi_b\\,F_y}",caption:{en:"A first size from the moment alone; the factor leaves room for the normal force — near 0.9 when N is small, near 0.7 when it is large. φb = 0.85.",ar:"أول مقاس من العزم لوحده؛ والمعامل بيسيب مكان للقوة العمودية — قريب من 0.9 لما N صغيرة، وقريب من 0.7 لما تكون كبيرة. و φb = 0.85."}},{t:"p",text:{en:"**Example.** $M_{ux} = 14$ m.t, St 37, a moderate normal force (factor 0.8): $S_x = 1400/(0.8\\times0.85\\times2.4) = 857.8$ cm³ → **IPE 360** ($S_x = 904$ cm³; IPE 330 has only 713).",ar:"**مثال.** $M_{ux} = 14$ م.طن، حديد 37، وقوة عمودية متوسطة (معامل 0.8): $S_x = 1400/(0.8\\times0.85\\times2.4) = 857.8$ سم³ ← **IPE 360** ($S_x = 904$ سم³؛ والـ IPE 330 فيه 713 بس)."}},{t:"p",text:{en:"In most shed columns the normal force is light, and **0.9** is the usual factor: $M_{ux} = 12$ m.t gives $S_x = 1200/(0.9\\times0.85\\times2.4) = 653.6$ cm³ → **IPE 330** ($S_x = 713$ cm³; IPE 300 has 557). The first size is only a start: the two limit states below decide.",ar:"في أغلب أعمدة الهناجر القوة العمودية خفيفة، والمعامل المعتاد **0.9**: $M_{ux} = 12$ م.طن بتدّي $S_x = 1200/(0.9\\times0.85\\times2.4) = 653.6$ سم³ ← **IPE 330** ($S_x = 713$ سم³؛ والـ IPE 300 فيه 557). أول مقاس مجرد بداية: الحالتين الحديتين اللي جايين هما اللي بيقرروا."}},{t:"quiz",q:{kind:"mcq",q:{en:"A built-up column of two channels bends in the plane of the frame. Its in-plane moment is written…",ar:"عمود مركب من مجريين بينحني في مستوى الإطار. العزم داخل المستوى بيتكتب…"},options:[{en:"M_y — about the axis between the chords",ar:"M_y — حوالين المحور اللي بين الفرعين"},{en:"M_x — about the strong axis of each channel",ar:"M_x — حوالين المحور القوي لكل مجرى"},{en:"M_z",ar:"M_z"}],answer:0,explain:{en:"For two chords the in-plane axis is y; x passes through both webs and belongs to the out-of-plane direction.",ar:"للفرعين المحور داخل المستوى هو y؛ و x بيعدّي على العصبين وبيخص الاتجاه خارج المستوى."}}}]},{id:"interaction",title:{en:"The capacities and the two limit states",ar:"المقاومات والحالتين الحديتين"},blocks:[{t:"p",text:{en:"A beam-column can fail in two ways. **In plane** (limit state 1, *in-plane instability*) it buckles in the plane of the frame, where the moment acts — its axial capacity is $P_{nx}$ from $\\lambda_x = L_{b,in}/r_x$. **Out of plane** (limit state 2, *flexural–torsional* or *out-of-plane instability*) it buckles sideways and twists: the axial capacity is $P_{ny}$ from $\\lambda_y = L_{b,out}/r_y$. The moment capacity $M_{nx}$ is **the same in both**: the moment of the section ($M_p$ for a compact section), reduced by lateral–torsional buckling of the compression flange whenever its unbraced length calls for it. Limit state 2 is often written with $M_{nx2}$ to recall that LTB check — it is the same value.",ar:"العمود اللي تحت حمل وعزم ممكن ينهار بطريقتين. **داخل المستوى** (الحالة الحدية 1، *عدم الاتزان داخل المستوى*) بينبعج في مستوى الإطار، مكان ما العزم شغال — مقاومته للضغط $P_{nx}$ من $\\lambda_x = L_{b,in}/r_x$. و**خارج المستوى** (الحالة الحدية 2، *انبعاج انحنائي–التوائي* أو *عدم الاتزان خارج المستوى*) بينبعج جانبيًا ويلف: مقاومة الضغط $P_{ny}$ من $\\lambda_y = L_{b,out}/r_y$. ومقاومة العزم $M_{nx}$ **هي هي في الاتنين**: عزم القطاع ($M_p$ للقطاع المدمج)، ناقص بالانبعاج الجانبي الالتوائي للشفة المضغوطة كل ما طولها غير المثبت يستدعي ده. الحالة الحدية 2 كتير بتتكتب بـ $M_{nx2}$ علشان تفكّرك بمراجعة الانبعاج الجانبي دي — وهي نفس القيمة."}},{t:"table",head:[{en:"Column of…",ar:"عمود…"},{en:"L_b,in (in the frame plane)",ar:"L_b,in (في مستوى الإطار)"}],rows:[[{en:"a trussed frame, hinged bases",ar:"إطار بجمالون، ركائز مفصلية"},"2 (h₂ + h₁/2)"],[{en:"a trussed frame, fixed bases",ar:"إطار بجمالون، ركائز ثابتة"},"1.2 (h₂ + h₁/2)"],[{en:"a cantilever (or double-cantilever) truss",ar:"جمالون كابولي (أو كابولي من الناحيتين)"},"2.1 (h₂ + h₁)"],[{en:"a Fink truss pinned on top, any cantilever column",ar:"جمالون فينك مفصلي فوق، وأي عمود كابولي"},"2.1 h"],[{en:"a frame held against sway (a tie)",ar:"إطار ممنوع من الحركة الجانبية (شداد)"},"h₂ + h₁"],[{en:"a rigid frame",ar:"إطار جاسئ"},{en:"K·h from G and the alignment chart (G = 10 hinged base, 1 fixed)",ar:"K·h من G ومنحنى المحاذاة (G = 10 للقاعدة المفصلية، و 1 للثابتة)"}]],caption:{en:"The buckling lengths of the previous lessons: h₂ is the column up to the lower chord, h₁ the truss depth at the column. Out of plane, L_b,out is the longest distance between the points held by the vertical bracing — the larger of h₁ and h₂ without struts. For the cantilever truss some designers take the shorter 2.1(h₂ + h₁/2); 2.1(h₂ + h₁) is on the safe side. Both slenderness ratios, in and out of plane, stay within 180.",ar:"أطوال الانبعاج من الدروس اللي فاتت: h₂ هو العمود لحد الوتر السفلي، و h₁ عمق الجمالون عند العمود. وخارج المستوى، L_b,out هو أطول مسافة بين النقط اللي الشكالات الرأسية ماسكاها — الأكبر من h₁ و h₂ من غير ستراتات. وللجمالون الكابولي فيه مصممين بياخدوا الطول الأقصر 2.1(h₂ + h₁/2)؛ و 2.1(h₂ + h₁) في ناحية الأمان. ونسبتين النحافة، داخل المستوى وخارجه، ميعدّوش 180."}},{t:"eq",tex:["\\lambda_c = \\dfrac{KL}{r}\\sqrt{\\dfrac{F_y}{\\pi^2 E}},\\qquad F_{cr} = F_y\\,(1 - 0.384\\lambda_c^2)\\ \\ (\\lambda_c \\le 1.1),\\qquad F_{cr} = \\dfrac{0.648F_y}{\\lambda_c^2}\\ \\ (\\lambda_c > 1.1)","P_n = A\\,F_{cr},\\qquad \\lambda \\le 180"],caption:{en:"The column curve, once with L_b,in and r_x (P_nx), once with L_b,out and r_y (P_ny). φ = 0.8 for compression.",ar:"منحنى الأعمدة، مرة بـ L_b,in و r_x (P_nx) ومرة بـ L_b,out و r_y (P_ny). و φ = 0.8 للضغط."}},{t:"eq",tex:["\\dfrac{P_u}{\\phi P_{nx}} \\ge 0.2:\\qquad \\dfrac{P_u}{\\phi P_{nx}} + \\dfrac{8}{9}\\left(\\dfrac{M_{ux}}{\\phi_b M_{nx}} + \\dfrac{M_{uy}}{\\phi_b M_{ny}}\\right) \\le 1.0","\\dfrac{P_u}{\\phi P_{nx}} < 0.2:\\qquad \\dfrac{P_u}{2\\,\\phi P_{nx}} + \\left(\\dfrac{M_{ux}}{\\phi_b M_{nx}} + \\dfrac{M_{uy}}{\\phi_b M_{ny}}\\right) \\le 1.0","\\dfrac{P_u}{\\phi P_{ny}} + \\left(\\dfrac{M_{ux}}{\\phi_b M_{nx}}\\right)^2 \\le 1.0"],caption:{en:"The first two lines are limit state 1 (in-plane instability): a straight line with a kink where P_u/φP_nx = 0.2. In both branches the second moment term is the weak-axis moment over its own capacity, M_uy/φbM_ny, with M_ny = 1.5·S_y·F_y for a compact section (S_y·F_y if non-compact) — bending about the weak axis has no LTB. The third line is limit state 2 (flexural–torsional, out-of-plane instability) of a doubly symmetric section bent about one axis. M_nx is the LTB-reduced moment in all three lines. φ = 0.8, φb = 0.85; M_u, P_u are second-order actions.",ar:"أول سطرين الحالة الحدية 1 (عدم الاتزان داخل المستوى): خط مستقيم فيه كسرة عند P_u/φP_nx = 0.2. وفي الفرعين حد العزم التاني هو عزم المحور الضعيف على مقاومته هو، M_uy/φbM_ny، و M_ny = 1.5·S_y·F_y للقطاع المدمج (و S_y·F_y لو غير مدمج) — الانحناء حوالين المحور الضعيف مفيهوش انبعاج جانبي التوائي. والسطر التالت الحالة الحدية 2 (انبعاج انحنائي–التوائي، عدم الاتزان خارج المستوى) لقطاع متماثل في الاتجاهين بينحني حوالين محور واحد. و M_nx هو العزم بعد الانبعاج الجانبي الالتوائي في التلات سطور. و φ = 0.8، و φb = 0.85؛ و M_u و P_u أحمال من الدرجة التانية."}},{t:"p",text:{en:"**Example.** An IPE 400 column of a trussed frame, St 37: $L_{b,in} = 12.5$ m, $L_{b,out} = 5.5$ m, the compression flange unbraced over 5.5 m with $C_b = 1.75$; $P_u = 18$ t and $M_{ux} = 17.0$ m.t (second-order). In plane: $\\lambda_x = 1250/16.5 = 75.8$, $\\lambda_c = 0.815$, $F_{cr} = 1.79$ t/cm², $P_{nx} = 151.0$ t, $\\phi P_{nx} = 120.8$ t. Out of plane: $\\lambda_y = 550/3.95 = 139.2$, $\\lambda_c = 1.50 > 1.1$, $F_{cr} = 0.693$ t/cm², $P_{ny} = 58.5$ t, $\\phi P_{ny} = 46.8$ t. Moment: $M_p = Z_xF_y = 1307\\times2.4 = 3137$ t.cm $= 31.37$ m.t, $\\phi_b M_p = 26.66$ m.t; LTB over 5.5 m (between $L_p = 204$ and $L_r = 620$ cm) with $C_b = 1.75$ gives 39.6 m.t, more than $M_p$, so $M_{nx} = M_p$ in both limit states.",ar:"**مثال.** عمود IPE 400 في إطار بجمالون، حديد 37: $L_{b,in} = 12.5$ م، و $L_{b,out} = 5.5$ م، والشفة المضغوطة غير مثبتة على 5.5 م و $C_b = 1.75$؛ و $P_u = 18$ طن و $M_{ux} = 17.0$ م.طن (من الدرجة التانية). داخل المستوى: $\\lambda_x = 1250/16.5 = 75.8$، و $\\lambda_c = 0.815$، و $F_{cr} = 1.79$ طن/سم²، و $P_{nx} = 151.0$ طن، و $\\phi P_{nx} = 120.8$ طن. خارج المستوى: $\\lambda_y = 550/3.95 = 139.2$، و $\\lambda_c = 1.50 > 1.1$، و $F_{cr} = 0.693$ طن/سم²، و $P_{ny} = 58.5$ طن، و $\\phi P_{ny} = 46.8$ طن. العزم: $M_p = Z_xF_y = 1307\\times2.4 = 3137$ طن.سم $= 31.37$ م.طن، و $\\phi_b M_p = 26.66$ م.طن؛ والانبعاج الجانبي على 5.5 م (بين $L_p = 204$ و $L_r = 620$ سم) بـ $C_b = 1.75$ بيدّي 39.6 م.طن، أكتر من $M_p$، يبقى $M_{nx} = M_p$ في الحالتين الحديتين."}},{t:"p",text:{en:"$P_u/\\phi P_{nx} = 18/120.8 = 0.149 < 0.2$, so $LS_1 = 0.149/2 + 17.0/26.66 = 0.075 + 0.638 = 0.71$ and $LS_2 = 18/46.8 + (17.0/26.66)^2 = 0.385 + 0.407 = 0.79$. Out of plane governs: the weak axis of the IPE, 5.5 m long, eats 38% of the capacity before any moment.",ar:"$P_u/\\phi P_{nx} = 18/120.8 = 0.149 < 0.2$، يبقى $LS_1 = 0.149/2 + 17.0/26.66 = 0.075 + 0.638 = 0.71$ و $LS_2 = 18/46.8 + (17.0/26.66)^2 = 0.385 + 0.407 = 0.79$. خارج المستوى هو اللي بيحكم: المحور الضعيف للـ IPE على طول 5.5 م بياكل 38% من المقاومة قبل أي عزم."}},{t:"lab",lab:"buckling",height:480,props:{preset:"beamcol",missions:t,defaultTab:"results"},caption:{en:"The IPE 400 column of the example in the N + M mode: the interaction diagram under the lab moves as you change the section, the lengths and the loads.",ar:"عمود الـ IPE 400 بتاع المثال في وضع N + M: منحنى التفاعل اللي تحت المعمل بيتحرك لما تغيّر القطاع والأطوال والأحمال."}},{t:"quiz",q:{kind:"num",q:{en:"P_u/φP_nx = 0.35 and M_ux/φbM_nx = 0.54 (no M_uy). LS₁?",ar:"P_u/φP_nx = 0.35 و M_ux/φbM_nx = 0.54 (مفيش M_uy). LS₁؟"},answer:.83,tol:.005,explain:{en:"Above 0.2: $0.35 + \\tfrac{8}{9}\\times0.54 = 0.35 + 0.48 = 0.83$.",ar:"فوق 0.2: $0.35 + \\tfrac{8}{9}\\times0.54 = 0.35 + 0.48 = 0.83$."}}}]},{id:"amplification",title:{en:"Second-order moments: B1 and B2",ar:"العزوم من الدرجة التانية: B1 و B2"},blocks:[{t:"p",text:{en:"A first-order analysis finds the moments on the undeformed frame. But the normal force acts on the **deformed** column and adds moments of its own: $P$ times the bulge $\\delta$ of the member between its ends (**P-δ**), and $P$ times the sway $\\Delta$ of the whole storey (**P-Δ**). The code multiplies the first-order moments: $M_{nt}$ (from loads that do not sway the frame) by $B_1$, and $M_{lt}$ (from the lateral translation) by $B_2$.",ar:"التحليل من الدرجة الأولى بيجيب العزوم على الإطار قبل ما يتشكل. لكن القوة العمودية شغالة على العمود **بعد ما اتشكل** وبتزوّد عزوم من عندها: $P$ في تقوّس العضو $\\delta$ بين طرفيه (**P-δ**)، و $P$ في الحركة الجانبية $\\Delta$ للدور كله (**P-Δ**). الكود بيضرب العزوم من الدرجة الأولى: $M_{nt}$ (من أحمال مش بتحرك الإطار جانبيًا) في $B_1$، و $M_{lt}$ (من الإزاحة الجانبية) في $B_2$."}},{t:"eq",tex:["M_u = B_1\\,M_{nt} + B_2\\,M_{lt},\\qquad P_u = P_{nt} + B_2\\,P_{lt}","B_1 = \\dfrac{C_m}{1 - P_u/P_{e1}} \\ge 1,\\qquad P_{e1} = \\dfrac{\\pi^2 E I}{(KL)^2}","B_2 = \\dfrac{1}{1 - \\Sigma P_u/\\Sigma P_{e2}} \\ge 1","B_2 = \\dfrac{1}{1 - \\dfrac{\\Sigma P_u\\,\\Delta_{oh}}{\\Sigma H\\,L}} \\ge 1"],caption:{en:"The two lines of B2 are alternatives: from the Euler loads or from the first-order drift. P_e1 with K of the member braced against sway (K ≤ 1, 1.0 on the safe side); P_e2 with K of the frame free to sway. ΣP_u: all the factored gravity of the storey — leaning columns included; ΣP_e2: over the columns that resist the sway; Δ_oh: first-order drift under the storey shear ΣH; L: storey height. When the actions come from a second-order analysis, the B factors are already inside.",ar:"سطرين B2 بديلين لبعض: من أحمال أويلر أو من الإزاحة من الدرجة الأولى. و P_e1 بـ K العضو المتربط ضد الحركة الجانبية (K ≤ 1، و 1.0 للأمان)؛ و P_e2 بـ K الإطار الحر في الحركة. و ΣP_u: كل الأحمال الرأسية المضروبة على الدور — ومعاها الأعمدة المستندة؛ و ΣP_e2: على الأعمدة اللي بتقاوم الحركة؛ و Δ_oh: الإزاحة من الدرجة الأولى تحت قص الدور ΣH؛ و L: ارتفاع الدور. ولو الأحمال طالعة من تحليل من الدرجة التانية، معاملات B بتبقى جواها أصلًا."}},{t:"p",text:{en:"**The IPE 400 frame again.** Its 17.0 m.t came from a first-order wind moment of 16 m.t: the frame sways, $P_{e2} = \\pi^2\\times2100\\times23130/1250^2 = 306.8$ t per column, $\\Sigma P_u/\\Sigma P_{e2} = 18/306.8 = 0.059$ (all columns alike), $B_2 = 1.062$ and $M_u = 1.062\\times16 = 17.0$ m.t. The bulge adds nothing: with $K = 1$ over 5.5 m, $P_{e1} = 1585$ t and $0.85/(1 - 18/1585) = 0.86$, so $B_1 = 1.0$.",ar:"**إطار الـ IPE 400 تاني.** الـ 17.0 م.طن بتوعه جايين من عزم رياح من الدرجة الأولى 16 م.طن: الإطار بيتحرك جانبيًا، و $P_{e2} = \\pi^2\\times2100\\times23130/1250^2 = 306.8$ طن لكل عمود، و $\\Sigma P_u/\\Sigma P_{e2} = 18/306.8 = 0.059$ (كل الأعمدة زي بعض)، و $B_2 = 1.062$ و $M_u = 1.062\\times16 = 17.0$ م.طن. والتقوّس مش بيزوّد حاجة: بـ $K = 1$ على 5.5 م، $P_{e1} = 1585$ طن و $0.85/(1 - 18/1585) = 0.86$، يبقى $B_1 = 1.0$."}},{t:"p",text:{en:"**Leaning columns.** Suppose the storey has 4 such frame columns and also 4 gravity-only columns of 40 t each (pinned at both ends, they resist no sway but they lean on the frames): $\\Sigma P_u = 4\\times18 + 4\\times40 = 232$ t, $\\Sigma P_{e2} = 4\\times306.8 = 1227$ t, the ratio becomes 0.189, $B_2 = 1.233$ and $M_u = 19.7$ m.t — $LS_1 = 0.81$, $LS_2 = 0.93$. The drift form gives the same idea: with $\\Delta_{oh} = 1.5$ cm under $\\Sigma H = 4$ t on a 5.5 m storey, $B_2 = 1/(1 - 232\\times1.5/(4\\times550)) = 1.19$.",ar:"**الأعمدة المستندة.** افرض الدور فيه 4 أعمدة إطار زي دول وكمان 4 أعمدة شايلة جاذبية بس، كل واحد 40 طن (مفصلية من الطرفين، مش بتقاوم أي حركة جانبية بس ساندة على الإطارات): $\\Sigma P_u = 4\\times18 + 4\\times40 = 232$ طن، و $\\Sigma P_{e2} = 4\\times306.8 = 1227$ طن، والنسبة بتبقى 0.189، و $B_2 = 1.233$ و $M_u = 19.7$ م.طن — و $LS_1 = 0.81$ و $LS_2 = 0.93$. وصيغة الإزاحة بتدّي نفس الفكرة: بـ $\\Delta_{oh} = 1.5$ سم تحت $\\Sigma H = 4$ طن على دور 5.5 م، $B_2 = 1/(1 - 232\\times1.5/(4\\times550)) = 1.19$."}},{t:"note",tone:"warn",text:{en:"As ΣP_u approaches ΣP_e2 the factor B2 grows without limit: the storey is about to buckle sideways under gravity alone, and no amount of section can save a moment check that ignores it.",ar:"لما ΣP_u تقرب من ΣP_e2 المعامل B2 بيكبر من غير حد: الدور على وشك إنه ينبعج جانبيًا تحت الجاذبية لوحدها، ومفيش قطاع هيلحق مراجعة عزم بتتجاهل ده."}},{t:"p",text:{en:"**Where $M_{nt}$ and $M_{lt}$ come from: superposition.** One frame analysis gives one moment diagram. The two parts that $B_1$ and $B_2$ need come from two analyses that add up to it:",ar:"**منين بييجوا $M_{nt}$ و $M_{lt}$: التجميع (تجميع التأثيرات).** تحليل واحد للإطار بيدّي منحنى عزوم واحد. والجزئين اللي $B_1$ و $B_2$ محتاجينهم بييجوا من تحليلين مجموعهم بيساويه:"}},{t:"steps",items:[{en:"**nt — the frame held.** Add a fictitious horizontal restraint at every floor level ($R_1$, $R_2$, … — one per storey) and analyse the frame under all the factored loads. It cannot sway: the moments are $M_{nt}$, the normal forces $P_{nt}$, and the restraints take the forces $R_1$, $R_2$, …",ar:"**nt — الإطار ممسوك.** حط سند أفقي وهمي عند كل منسوب دور ($R_1$ و $R_2$ … — واحد لكل دور) وحلّل الإطار تحت كل الأحمال المضروبة. الإطار مش هيقدر يتحرك جانبيًا: العزوم هي $M_{nt}$ والقوى العمودية $P_{nt}$، والسنود الوهمية بتاخد القوى $R_1$ و $R_2$ …"},{en:"**lt — the frame released.** Remove the restraints and load the free frame with $R_1$, $R_2$, … **reversed** — nothing else. Now it sways: $M_{lt}$, $P_{lt}$ and the first-order drift $\\Delta_{oh}$ under the storey shear $\\Sigma H = R$.",ar:"**lt — الإطار حر.** شيل السنود وحمّل الإطار الحر بـ $R_1$ و $R_2$ … **معكوسة** — ومفيش أي حمل تاني. دلوقتي بيتحرك جانبيًا: $M_{lt}$ و $P_{lt}$ والإزاحة من الدرجة الأولى $\\Delta_{oh}$ تحت قص الدور $\\Sigma H = R$."},{en:"**Check, then amplify.** $M_{nt} + M_{lt}$ is the first-order result of the free frame; then $M_u = B_1M_{nt} + B_2M_{lt}$ and $P_u = P_{nt} + B_2P_{lt}$, each with its sign.",ar:"**راجع، وبعدين كبّر.** $M_{nt} + M_{lt}$ هو نتيجة الدرجة الأولى للإطار الحر؛ وبعدين $M_u = B_1M_{nt} + B_2M_{lt}$ و $P_u = P_{nt} + B_2P_{lt}$، كل واحد بإشارته."}]},{t:"p",text:{en:"**Example.** A portal frame of 15 m span on hinged bases: IPE 400 columns 6 m high, an IPE 500 beam. Factored loads: 1.6 t/m on the beam, a wind of 0.5 t/m on the windward column and 0.3 t/m of suction on the leeward one (both towards the leeward side). **nt:** a restraint at the eaves takes $R = 2.76$ t; the knee moments are 20.51 m.t (windward) and 18.34 m.t (leeward), both with tension on the outer face; $P_{nt} = 12.14$ and 11.86 t. **lt:** the 2.76 t applied reversed at the eaves of the free frame give 8.28 m.t at the windward knee and 8.29 m.t at the leeward one — tension inside on the windward column, outside on the leeward one — a drift $\\Delta_{oh} = 3.28$ cm and $P_{lt} = \\mp1.10$ t. The sums, 12.23 and 26.63 m.t, are exactly what the free frame gives in one analysis. **Amplify:** $\\Sigma P_u = 1.6\\times15 = 24$ t, $B_2 = 1/(1 - 24\\times3.28/(2.76\\times600)) = 1.050$. The leeward column carries its suction between a hinged base and the knee, so $C_m = 1.0$; with $P_{e1} = 1332$ t ($K = 1$) $B_1 = 1.010$. So $P_u = 11.86 + 1.050\\times1.10 = 13.02$ t and $M_u = 1.010\\times18.34 + 1.050\\times8.29 = 27.22$ m.t at the leeward knee — the leeward column governs, since on the windward one the sway moment works against the held one.",ar:"**مثال.** إطار بوابي بحر 15 م على ركائز مفصلية: أعمدة IPE 400 ارتفاعها 6 م، وكمرة IPE 500. الأحمال المضروبة: 1.6 طن/م على الكمرة، ورياح 0.5 طن/م على العمود المواجه و 0.3 طن/م سحب على العمود الخلفي (الاتنين ناحية الخلفي). **nt:** سند عند منسوب الركن بياخد $R = 2.76$ طن؛ وعزوم الأركان 20.51 م.طن (المواجه) و 18.34 م.طن (الخلفي)، الاتنين والشد على الوش الخارجي؛ و $P_{nt} = 12.14$ و 11.86 طن. **lt:** الـ 2.76 طن معكوسة عند منسوب الركن على الإطار الحر بيدّوا 8.28 م.طن عند ركن المواجه و 8.29 م.طن عند ركن الخلفي — الشد جوّه في العمود المواجه وبرّه في الخلفي — وإزاحة $\\Delta_{oh} = 3.28$ سم و $P_{lt} = \\mp1.10$ طن. المجموع، 12.23 و 26.63 م.طن، هو بالظبط اللي الإطار الحر بيدّيه في تحليل واحد. **التكبير:** $\\Sigma P_u = 1.6\\times15 = 24$ طن، و $B_2 = 1/(1 - 24\\times3.28/(2.76\\times600)) = 1.050$. العمود الخلفي شايل السحب على طوله بين قاعدة مفصلية والركن، يبقى $C_m = 1.0$؛ ومع $P_{e1} = 1332$ طن ($K = 1$) يبقى $B_1 = 1.010$. يبقى $P_u = 11.86 + 1.050\\times1.10 = 13.02$ طن و $M_u = 1.010\\times18.34 + 1.050\\times8.29 = 27.22$ م.طن عند ركن العمود الخلفي — والخلفي هو اللي بيحكم، لأن في المواجه عزم الحركة الجانبية شغال عكس عزم الإطار الممسوك."}},{t:"eq",tex:["B_{1x} = \\dfrac{C_{mx}}{1 - P_u/P_{e1x}} \\ge 1,\\qquad P_{e1x} = \\dfrac{\\pi^2 E A}{(KL/r_x)^2}","B_{1y} = \\dfrac{C_{my}}{1 - P_u/P_{e1y}} \\ge 1,\\qquad P_{e1y} = \\dfrac{\\pi^2 E A}{(KL/r_y)^2}"],caption:{en:"A column bent about both axes takes a B₁ for each moment, each with its own Euler load (K of the member braced against sway, 1.0 on the safe side; π²EA/(KL/r)² is the same load as π²EI/(KL)²) and its own Cm. Cmx asks: may the column sway in the X direction, the plane of M_x? Then 0.85; if not, Cm from α or from the loads along it. Cmy asks the same question for the Y direction.",ar:"العمود اللي بينحني حوالين المحورين بياخد B₁ لكل عزم، كل واحد بحمل أويلر بتاعه (K العضو المتربط ضد الحركة الجانبية، و 1.0 للأمان؛ و π²EA/(KL/r)² هو نفس الحمل π²EI/(KL)²) و Cm بتاعه. Cmx بيسأل: العمود يقدر يتحرك جانبيًا في اتجاه X، مستوى M_x؟ يبقى 0.85؛ ولو لأ، Cm من α أو من الأحمال اللي على طوله. و Cmy بيسأل نفس السؤال لاتجاه Y."}},{t:"p",text:{en:"**Example.** An HEB 240 corner column, 5.0 m, $P_u = 40$ t. Across the building it belongs to a frame that sways: $C_{mx} = 0.85$. Along the building the vertical bracing stops the sway, and the gable wind loads the column along its height between hinged ends: $C_{my} = 1.0$. With $K = 1$: $P_{e1x} = \\pi^2\\times2100\\times106/(500/10.3)^2 = 932$ t and $0.85/(1 - 40/932) = 0.89$, so $B_{1x} = 1.0$; $P_{e1y} = \\pi^2\\times2100\\times106/(500/6.08)^2 = 325$ t and $B_{1y} = 1/(1 - 40/325) = 1.14$. A first-order gable-wind moment of $0.8\\times5^2/8 = 2.5$ m.t becomes $M_{uy} = 2.85$ m.t — the weak axis amplifies, the strong one does not.",ar:"**مثال.** عمود ركن HEB 240، طوله 5.0 م، و $P_u = 40$ طن. بعرض المبنى هو جزء من إطار بيتحرك جانبيًا: $C_{mx} = 0.85$. وبطول المبنى الشكالات الرأسية مانعة الحركة، ورياح الواجهة شغالة على طول العمود بين طرفين مفصليين: $C_{my} = 1.0$. بـ $K = 1$: $P_{e1x} = \\pi^2\\times2100\\times106/(500/10.3)^2 = 932$ طن و $0.85/(1 - 40/932) = 0.89$، يبقى $B_{1x} = 1.0$؛ و $P_{e1y} = \\pi^2\\times2100\\times106/(500/6.08)^2 = 325$ طن و $B_{1y} = 1/(1 - 40/325) = 1.14$. وعزم رياح الواجهة من الدرجة الأولى $0.8\\times5^2/8 = 2.5$ م.طن بيبقى $M_{uy} = 2.85$ م.طن — المحور الضعيف بيكبّر والقوي لأ."}},{t:"lab",lab:"buckling",height:480,props:{preset:"bcAmplify",missions:a,defaultTab:"inputs"},caption:{en:"A cantilever column of HEB 260, 7 m, under a Fink truss, with 25 t of leaning gravity per column: B₂ = 1.54. Slide the leaning load and watch the amplification chart below.",ar:"عمود كابولي HEB 260 طوله 7 م تحت جمالون فينك، و 25 طن أحمال مستندة لكل عمود: B₂ = 1.54. حرّك الحمل المستند وشوف منحنى التكبير اللي تحت."}},{t:"quiz",q:{kind:"num",q:{en:"ΣP_u = 150 t, ΣP_e2 = 600 t. B₂?",ar:"ΣP_u = 150 طن، و ΣP_e2 = 600 طن. B₂؟"},answer:1.333,tol:.005,explain:{en:"$1/(1 - 150/600) = 1/0.75 = 1.333$.",ar:"$1/(1 - 150/600) = 1/0.75 = 1.333$."}}}]},{id:"factors",title:{en:"Cm, Cb and α of typical column diagrams",ar:"Cm و Cb و α لمنحنيات الأعمدة النمطية"},blocks:[{t:"p",text:{en:"Both factors describe the shape of the moment diagram. $\\alpha = M_1/M_2$ is the smaller over the larger end moment of the segment: **positive in double curvature** (the ends bend the column into an S), **negative in single curvature**. A uniform moment ($\\alpha = -1$) is the worst case for both the bulge and the flange: $C_m = 1.0$ and $C_b = 1.0$.",ar:"المعاملين بيوصفوا شكل منحنى العزوم. $\\alpha = M_1/M_2$ هي العزم الأصغر على العزم الأكبر عند طرفي الجزء: **موجبة في الانحناء المزدوج** (الطرفين بيحنوا العمود على شكل S)، و**سالبة في الانحناء في اتجاه واحد**. العزم المنتظم ($\\alpha = -1$) هو أسوأ حالة للتقوّس وللشفة: $C_m = 1.0$ و $C_b = 1.0$."}},{t:"eq",tex:["C_b = 1.75 + 1.05\\,\\alpha + 0.3\\,\\alpha^2 \\le 2.3","C_b = \\dfrac{12.5\\,M_{max}}{2.5\\,M_{max} + 3M_a + 4M_b + 3M_c}","C_m = 0.85,\\qquad C_m = 0.6 - 0.4\\,\\alpha \\ge 0.4"],caption:{en:"First line: a segment braced at both ends with a straight moment diagram. Second: whenever the moment somewhere inside the unbraced length is larger than both end moments (a curved diagram, a load between the braces), with the largest moment and the absolute moments at the quarter points a, b, c. Third: Cm in a frame free to sway (0.85), and for a braced member without loads between its ends; a braced member loaded along its length takes 0.85 with restrained ends, 1.0 with hinged ends.",ar:"السطر الأول: جزء متثبت من طرفيه ومنحنى عزومه خط مستقيم. التاني: كل ما يكون فيه عزم جوّه الطول غير المثبت أكبر من عزمي الطرفين الاتنين (منحنى منحني، أو حمل بين نقط التثبيت)، بأكبر عزم وبالعزوم المطلقة عند نقط الأرباع a و b و c. التالت: Cm في إطار حر يتحرك جانبيًا (0.85)، ولعضو متربط من غير أحمال بين طرفيه؛ والعضو المتربط اللي عليه حمل على طوله بياخد 0.85 لو طرفيه متثبتين و 1.0 لو مفصليين."}},{t:"table",head:[{en:"Column of…",ar:"عمود…"},"α","C_b","C_m"],rows:[[{en:"a trussed frame, hinged bases",ar:"إطار بجمالون، ركائز مفصلية"},"0","1.75","0.85"],[{en:"a trussed frame, fixed bases",ar:"إطار بجمالون، ركائز ثابتة"},"≈ +0.5","2.35 → 2.3","0.85"],[{en:"a Fink truss pinned on top",ar:"جمالون فينك مفصلي فوق"},"0","1.75","0.85"],[{en:"a cantilever truss",ar:"جمالون كابولي"},"−1","1.0","0.85"],[{en:"a truss with a tie (no sway, hinged base)",ar:"جمالون بشداد (مفيش حركة، قاعدة مفصلية)"},"0","1.75","0.6"],[{en:"a hinged column with a strut at mid-height (upper half, L_b = h/2)",ar:"عمود مفصلي بستراتة في نص الارتفاع (النص العلوي، و L_b = h/2)"},"−0.5","1.30","0.85"],[{en:"a Fink truss pinned on top, strut at mid-height: upper half (0 → M/2)",ar:"جمالون فينك مفصلي فوق، وستراتة في نص الارتفاع: النص العلوي (0 ← M/2)"},"0","1.75","0.85"],[{en:"the same, lower half (M/2 → M at the fixed base), L_u,act = L_u,out = h/2",ar:"نفس العمود، النص السفلي (M/2 ← M عند القاعدة الثابتة)، و L_u,act = L_u,out = h/2"},"−0.5","1.30","0.85"]],caption:{en:"Typical straight-line diagrams. The hinged base gives zero moment at the base; the fixed base bends the column in double curvature with a base moment about half the top moment; the cantilever truss hands the column a constant moment.",ar:"منحنيات نمطية على شكل خط مستقيم. الركيزة المفصلية بتدّي عزم صفر عند القاعدة؛ والثابتة بتحني العمود انحناء مزدوج وعزم القاعدة حوالي نص عزم الراس؛ والجمالون الكابولي بيدّي العمود عزم ثابت."}},{t:"p",text:{en:"**Combined and roof columns.** In a stepped crane column each part is a segment of its own, between the base, the crane level and the truss — take α from its end moments. Example: a column fixed at its base, a crane part of 5 m and a roof part of 2.5 m with half the inertia, the truss holding the top against rotation, a wind of 0.4 t/m along it. A frame analysis gives 2.92 m.t at the top, 1.67 m.t at the step and −8.33 m.t at the base. The **roof column** bends in single curvature: $\\alpha = -1.67/2.92 = -0.57$, $C_b = 1.25$; the **crane column** in double curvature: $\\alpha = +1.67/8.33 = +0.20$, $C_b = 1.97$; both sway, $C_m = 0.85$.",ar:"**عمود الونش وعمود السقف.** في عمود الونش المتدرج كل جزء ليه لوحده، بين القاعدة ومنسوب الونش والجمالون — خد α من العزوم اللي على طرفيه. مثال: عمود قاعدته ثابتة، جزء الونش 5 م وجزء السقف 2.5 م بنص القصور الذاتي، والجمالون ماسك الراس ضد الدوران، ورياح 0.4 طن/م على طوله. التحليل بيدّي 2.92 م.طن عند الراس، و 1.67 م.طن عند التدريجة، و −8.33 م.طن عند القاعدة. **عمود السقف** بينحني في اتجاه واحد: $\\alpha = -1.67/2.92 = -0.57$، و $C_b = 1.25$؛ و**عمود الونش** انحناء مزدوج: $\\alpha = +1.67/8.33 = +0.20$، و $C_b = 1.97$؛ والاتنين بيتحركوا جانبيًا، $C_m = 0.85$."}},{t:"p",text:{en:"**Curved diagrams.** Wind along a cantilever column gives $M \\propto (1 - x/h)^2$, not a straight line: at the quarter points 0.563, 0.25 and 0.063 of the base moment, so $C_b = 12.5/(2.5 + 1.688 + 1.0 + 0.188) = 2.33$ — kinder than the 1.75 of the straight line. **Cm:** a braced column with end moments of 8 and 4 m.t in double curvature has $\\alpha = +0.5$ and $C_m = 0.6 - 0.2 = 0.4$; in single curvature $\\alpha = -0.5$ and $C_m = 0.8$.",ar:"**المنحنيات المنحنية.** الرياح على طول عمود كابولي بتدّي $M \\propto (1 - x/h)^2$، مش خط مستقيم: عند نقط الأرباع 0.563 و 0.25 و 0.063 من عزم القاعدة، يبقى $C_b = 12.5/(2.5 + 1.688 + 1.0 + 0.188) = 2.33$ — أرحم من الـ 1.75 بتاعة الخط المستقيم. **و Cm:** عمود متربط عزوم طرفيه 8 و 4 م.طن في انحناء مزدوج ليه $\\alpha = +0.5$ و $C_m = 0.6 - 0.2 = 0.4$؛ وفي انحناء في اتجاه واحد $\\alpha = -0.5$ و $C_m = 0.8$."}},{t:"lab",lab:"buckling",height:480,props:{preset:"bcFrames",missions:n,defaultTab:"results"},caption:{en:"The gallery under the lab shows the diagram, α, Cb and Cm of every frame type; click one to load it, or switch the diagram to the curved wind shape.",ar:"المعرض اللي تحت المعمل بيوري المنحنى و α و Cb و Cm لكل نوع إطار؛ اضغط على واحد يتحمّل، أو حوّل المنحنى لشكل الرياح المنحني."}},{t:"quiz",q:{kind:"num",q:{en:"A braced column without loads between its ends: end moments 6 and 3 m.t in single curvature. Cm?",ar:"عمود متربط من غير أحمال بين طرفيه: عزوم الطرفين 6 و 3 م.طن في انحناء في اتجاه واحد. Cm؟"},answer:.8,tol:.005,explain:{en:"Single curvature: $\\alpha = -3/6 = -0.5$, $C_m = 0.6 + 0.2 = 0.8$.",ar:"انحناء في اتجاه واحد: $\\alpha = -3/6 = -0.5$، و $C_m = 0.6 + 0.2 = 0.8$."}}}]},{id:"ltb",title:{en:"Lateral–torsional buckling of the column",ar:"الانبعاج الجانبي الالتوائي للعمود"},blocks:[{t:"p",text:{en:"The compressed flange of a column bent about its strong axis is itself a small column: between the points that hold it sideways it can buckle out of plane, twisting the section. The moment capacity $M_{nx}$ — the one value used in both limit states (often written $M_{nx2}$) — follows the LTB curve of the beams, with three zones (for a compact section — a non-compact one has a lower plateau, $M_{nx1}$, shown with the local-buckling checks below):",ar:"الشفة المضغوطة في عمود بينحني حوالين محوره القوي هي نفسها عمود صغير: بين النقط اللي ماسكاها جانبيًا تقدر تنبعج خارج المستوى وتلف القطاع معاها. مقاومة العزم $M_{nx}$ — القيمة الواحدة اللي بتدخل الحالتين الحديتين (وكتير بتتكتب $M_{nx2}$) — ماشية على منحنى الانبعاج الجانبي بتاع الكمرات، وفيه تلات مناطق (للقطاع المدمج — وغير المدمج ليه جزء أفقي أوطى، $M_{nx1}$، موجود مع مراجعات الانبعاج الموضعي تحت):"}},{t:"eq",tex:["L_p = \\dfrac{80\\,r_y}{\\sqrt{F_y}},\\qquad L_r = \\dfrac{1380\\,A_f}{d\\,F_L}\\sqrt{\\tfrac{1}{2}\\left[1 + \\sqrt{1 + (2XF_L)^2}\\right]},\\qquad X = \\left(\\dfrac{0.104\\,r_T\\,d}{A_f}\\right)^2","r_T = \\sqrt{\\dfrac{t_f b_f^3/12}{t_f b_f + t_w h_w/6}},\\qquad M_p = Z_x F_y \\approx 1.13\\,S_x F_y,\\qquad M_r = S_x F_L","L_p < L_u \\le L_r:\\quad M_n = C_b\\left[M_p - (M_p - M_r)\\dfrac{L_u - L_p}{L_r - L_p}\\right] \\le M_p","L_u > L_r:\\quad M_n = C_b\\,S_x\\sqrt{\\left(\\dfrac{1380\\,A_f}{d\\,L_u}\\right)^2 + \\left(\\dfrac{20700}{(L_u/r_T)^2}\\right)^2} \\le M_p"],caption:{en:"Up to L_p the full plastic moment; between L_p and L_r a straight line down to M_r (inelastic); beyond L_r elastic LTB. L_u (L_b) is the distance between the points that hold the compression flange against moving sideways, or the section against twisting; L_p is the longest such length that still lets the section reach M_p. A_f = b_f·t_f, d the depth, F_L = 0.75F_y for rolled sections (0.6F_y built-up); lengths in cm, F in t/cm².",ar:"لحد L_p العزم اللدن كامل؛ وبين L_p و L_r خط مستقيم نازل لـ M_r (غير مرن)؛ وبعد L_r انبعاج جانبي مرن. و L_u (أو L_b) هو المسافة بين النقط اللي ماسكة الشفة المضغوطة من إنها تتحرك جانبيًا، أو ماسكة القطاع من إنه يلف؛ و L_p أطول مسافة من دي لسه بتسيب القطاع يوصل لـ M_p. و A_f = b_f·t_f، و d العمق، و F_L = 0.75F_y للقطاعات المدرفلة (و 0.6F_y للمركبة)؛ الأطوال بالسم و F بالطن/سم²."}},{t:"p",text:{en:"**Example.** IPE 360, St 37: $L_p = 80\\times3.79/\\sqrt{2.4} = 196$ cm; $A_f = 17\\times1.27 = 21.59$ cm², $r_T = 4.47$ cm, $X = 0.600$, $F_L = 1.8$, $L_r = 598$ cm; $M_p = 1019\\times2.4 = 24.46$ m.t, $M_r = 904\\times1.8 = 16.27$ m.t. Over $L_u = 3.5$ m with $C_b = 1.30$ (inelastic): $1.30\\,[2446 - 818\\times(350 - 196)/(598 - 196)] = 2771$ t.cm, above $M_p$, so the full 24.46 m.t. Over $L_u = 7.0$ m with $C_b = 1.75$ (elastic): **22.97 m.t** — the unbraced flange costs 6%.",ar:"**مثال.** IPE 360، حديد 37: $L_p = 80\\times3.79/\\sqrt{2.4} = 196$ سم؛ و $A_f = 17\\times1.27 = 21.59$ سم²، و $r_T = 4.47$ سم، و $X = 0.600$، و $F_L = 1.8$، و $L_r = 598$ سم؛ و $M_p = 1019\\times2.4 = 24.46$ م.طن، و $M_r = 904\\times1.8 = 16.27$ م.طن. على $L_u = 3.5$ م و $C_b = 1.30$ (غير مرن): $1.30\\,[2446 - 818\\times(350 - 196)/(598 - 196)] = 2771$ طن.سم، أكبر من $M_p$، يبقى الـ 24.46 م.طن كاملين. وعلى $L_u = 7.0$ م و $C_b = 1.75$ (مرن): **22.97 م.طن** — الشفة غير المثبتة بتكلف 6%."}},{t:"quiz",q:{kind:"num",q:{en:"HEB 200 (r_y = 5.07 cm), St 37. L_p (cm)?",ar:"HEB 200 (r_y = 5.07 سم)، حديد 37. L_p (سم)؟"},answer:261.8,tol:.003,unit:"cm",explain:{en:"$80\\times5.07/\\sqrt{2.4} = 405.6/1.549 = 261.8$ cm.",ar:"$80\\times5.07/\\sqrt{2.4} = 405.6/1.549 = 261.8$ سم."}}}]},{id:"local",title:{en:"Local buckling under N + M: the web and the flanges",ar:"الانبعاج الموضعي تحت N + M: العصب والشفف"},blocks:[{t:"p",text:{en:"Bending leaves part of the web in tension; the normal force pushes the neutral axis down and compresses more of it. So the limit of the web depends on how much of it is compressed. The flange outstand $c = (b - t_w - 2r)/2$ keeps its usual limits: $c/t_f \\le 16.9/\\sqrt{F_y}$ compact and $23/\\sqrt{F_y}$ non-compact for rolled sections; $15.3/\\sqrt{F_y}$ and $21/\\sqrt{F_y}$ for welded ones. These non-compact limits belong to a flange that the normal force compresses too; a flange in bending alone — a beam, a crane girder — may go up to $28/\\sqrt{F_y} = 18.1$ (St 37) before it turns slender, with the same compact limits (crane girder lessons).",ar:"الانحناء بيسيب جزء من العصب في شد؛ والقوة العمودية بتنزّل محور التعادل وبتضغط جزء أكبر منه. علشان كده حد العصب بيعتمد على الجزء المضغوط منه قد إيه. والجزء البارز من الشفة (Outstand) $c = (b - t_w - 2r)/2$ ليه حدوده المعتادة: $c/t_f \\le 16.9/\\sqrt{F_y}$ مدمج و $23/\\sqrt{F_y}$ غير مدمج للقطاعات المدرفلة؛ و $15.3/\\sqrt{F_y}$ و $21/\\sqrt{F_y}$ للملحومة. حدود غير المدمج دي لشفة القوة العمودية بتضغطها كمان؛ أما الشفة اللي تحت انحناء لوحده — كمرة، أو كمرة ونش — فممكن توصل لـ $28/\\sqrt{F_y} = 18.1$ (حديد 37) قبل ما تبقى نحيفة، بنفس حدود المدمج (دروس كمرات الأوناش)."}},{t:"eq",tex:["\\alpha = \\dfrac{1}{h_w}\\left(\\dfrac{h}{2} + \\dfrac{P_u}{2t_wF_y} - t_f\\right) = \\dfrac{1}{2}\\left(\\dfrac{P_u}{h_w t_w F_y} + 1\\right)","\\alpha > 0.5:\\ \\ \\dfrac{d_w}{t_w} \\le \\dfrac{699/\\sqrt{F_y}}{13\\alpha - 1},\\qquad \\alpha \\le 0.5:\\ \\ \\dfrac{d_w}{t_w} \\le \\dfrac{63.6}{\\alpha\\sqrt{F_y}}","\\psi = \\dfrac{-N/A + M/S}{-N/A - M/S}:\\qquad \\psi > -1:\\ \\dfrac{d_w}{t_w} \\le \\dfrac{222}{(2 + \\psi)\\sqrt{F_y}},\\qquad \\psi \\le -1:\\ \\dfrac{d_w}{t_w} \\le \\dfrac{111\\,(1 - \\psi)\\sqrt{-\\psi}}{\\sqrt{F_y}}"],caption:{en:"Compact: α is the compressed part of the web at full plasticity (N positive in compression), valid while P_u ≤ h_w·t_w·F_y — the plastic neutral axis in the web. Non-compact: ψ is the ratio of the elastic edge stresses. If P_u > h_w·t_w·F_y the whole web is compressed: 58/√F_y compact, 64/√F_y non-compact. h_w = h − 2t_f, d_w = h_w − 2r.",ar:"المدمج: α هي الجزء المضغوط من العصب عند اللدونة الكاملة (N موجبة في الضغط)، وده صح طول ما P_u ≤ h_w·t_w·F_y — محور التعادل اللدن جوه العصب. غير المدمج: ψ نسبة الإجهادات المرنة عند حرفي العصب. ولو P_u > h_w·t_w·F_y العصب كله مضغوط: 58/√F_y مدمج و 64/√F_y غير مدمج. و h_w = h − 2t_f، و d_w = h_w − 2r."}},{t:"p",text:{en:"Two checks of the formulas: pure bending gives $\\alpha = 0.5$ and $63.6/0.5 = 127/\\sqrt{F_y}$, the web of a beam; $\\alpha = 1$ gives $699/12 = 58/\\sqrt{F_y}$, the web of a column. **Example.** IPE 360, St 37, $P_u = 60$ t, $M_u = 10$ m.t: $h_w = 33.46$ cm, $h_wt_wF_y = 64.2$ t $> 60$ → $\\alpha = \\tfrac{1}{2}(60/64.2 + 1) = 0.967$, limit $451.2/(13\\times0.967 - 1) = 39.0 \\ge d_w/t_w = 29.86/0.8 = 37.3$ — compact. $\\psi = -0.145$ gives a non-compact limit of 77.3; the flange: $c/t_f = 6.30/1.27 = 4.96 \\le 10.9$. At $P_u = 70$ t the whole web is compressed and the limit falls to $58/\\sqrt{2.4} = 37.4$ — still (just) compact.",ar:"مراجعتين للمعادلات: الانحناء لوحده بيدّي $\\alpha = 0.5$ و $63.6/0.5 = 127/\\sqrt{F_y}$، عصب الكمرة؛ و $\\alpha = 1$ بتدّي $699/12 = 58/\\sqrt{F_y}$، عصب العمود. **مثال.** IPE 360، حديد 37، و $P_u = 60$ طن، و $M_u = 10$ م.طن: $h_w = 33.46$ سم، و $h_wt_wF_y = 64.2$ طن $> 60$ ← $\\alpha = \\tfrac{1}{2}(60/64.2 + 1) = 0.967$، والحد $451.2/(13\\times0.967 - 1) = 39.0 \\ge d_w/t_w = 29.86/0.8 = 37.3$ — مدمج. و $\\psi = -0.145$ بتدّي حد غير مدمج 77.3؛ والشفة: $c/t_f = 6.30/1.27 = 4.96 \\le 10.9$. وعند $P_u = 70$ طن العصب كله بيتضغط والحد بينزل لـ $58/\\sqrt{2.4} = 37.4$ — لسه مدمج (على الحركرك)."}},{t:"p",text:{en:"**The quick form with $d_w$.** The same check is often made with the flat web $d_w$ in both places: the neutral axis lies in the web while $N < d_w\\,t_w\\,F_y$ (the web area times the yield stress), then $\\alpha = \\tfrac{1}{2}\\left(N/(d_wt_wF_y) + 1\\right)$, compared with $d_w/t_w$ — $N$ positive in compression, negative in tension. It gives a slightly larger α, so a slightly stricter limit. For the IPE 360: $d_wt_wF_y = 29.86\\times0.8\\times2.4 = 57.3$ t. At $P_u = 50$ t, $\\alpha = \\tfrac{1}{2}(50/57.3 + 1) = 0.936$ and the limit is 40.4 (with $h_w$: $\\alpha = 0.889$ and 42.7). At $P_u = 60$ t the quick form already finds the whole web compressed — 37.4 against 37.3: compact by both routes.",ar:"**الصيغة السريعة بـ $d_w$.** نفس المراجعة كتير بتتعمل بالعصب المستقيم $d_w$ في المكانين: محور التعادل جوّه العصب طول ما $N < d_w\\,t_w\\,F_y$ (مساحة العصب في إجهاد الخضوع)، ووقتها $\\alpha = \\tfrac{1}{2}\\left(N/(d_wt_wF_y) + 1\\right)$، وبتتقارن بـ $d_w/t_w$ — و $N$ موجبة في الضغط وسالبة في الشد. بتدّي α أكبر شوية، يعني حد أشد شوية. للـ IPE 360: $d_wt_wF_y = 29.86\\times0.8\\times2.4 = 57.3$ طن. عند $P_u = 50$ طن، $\\alpha = \\tfrac{1}{2}(50/57.3 + 1) = 0.936$ والحد 40.4 (وبـ $h_w$: $\\alpha = 0.889$ و 42.7). وعند $P_u = 60$ طن الصيغة السريعة بتلاقي العصب كله مضغوط من الأول — 37.4 قصاد 37.3: مدمج بالطريقتين."}},{t:"table",head:[{en:"Element (ratio)",ar:"العنصر (النسبة)"},{en:"Compact",ar:"مدمج"},{en:"Non-compact",ar:"غير مدمج"}],rows:[[{en:"flange outstand c/t_f, rolled, under N + M",ar:"الجزء البارز من الشفة c/t_f، مدرفل، تحت N + M"},"16.9/√F_y (10.9)","23/√F_y (14.8)"],[{en:"flange outstand c/t_f, welded, under N + M",ar:"الجزء البارز من الشفة c/t_f، ملحوم، تحت N + M"},"15.3/√F_y (9.9)","21/√F_y (13.6)"],[{en:"flange outstand in bending alone (beams, crane girders)",ar:"الجزء البارز من شفة تحت انحناء بس (كمرات، كمرات أوناش)"},{en:"16.9/√F_y (10.9) rolled, 15.3/√F_y (9.9) welded",ar:"16.9/√F_y (10.9) مدرفل، و 15.3/√F_y (9.9) ملحوم"},"28/√F_y (18.1)"],[{en:"internal flange element b/t_f: the flange of a box, a built-up box or an RHS between two webs, in bending or in compression",ar:"عنصر شفة داخلي b/t_f: شفة صندوق أو صندوق مركب أو قطاع مستطيل أجوف (RHS) بين عصبين، في انحناء أو في ضغط"},"58/√F_y (37.4)","64/√F_y (41.3)"],[{en:"web d_w/t_w in pure bending (α = 0.5, ψ = −1)",ar:"العصب d_w/t_w في انحناء بس (α = 0.5، ψ = −1)"},"127/√F_y (82.0)","222/√F_y (143.3)"],[{en:"web d_w/t_w, neutral axis inside it",ar:"العصب d_w/t_w، ومحور التعادل جوّاه"},"699/((13α − 1)√F_y) · 63.6/(α√F_y)","222/((2 + ψ)√F_y) · 111(1 − ψ)√(−ψ)/√F_y"],[{en:"web d_w/t_w, wholly compressed",ar:"العصب d_w/t_w، مضغوط كله"},"58/√F_y (37.4)","64/√F_y (41.3)"]],caption:{en:"Limits over √F_y with F_y in t/cm²; St 37 values in brackets; b is the clear width between the webs. The compact web limits are not meant for a single channel. A compact section reaches M_p; a non-compact one stops below it, at M_nx1 (below). The chords of a built-up column, which have no LTB, take M_p when they pass 16.9/√F_y (10.9) and 58/√F_y (37.44), and simply M_n = M_y = S·F_y when they are only non-compact.",ar:"الحدود مقسومة على √F_y و F_y بالطن/سم²؛ وقيم حديد 37 بين القوسين؛ و b العرض الصافي بين العصبين. حدود العصب المدمج مش معمولة لمجرى (Channel) لوحده. القطاع المدمج بيوصل لـ M_p؛ وغير المدمج بيقف تحته، عند M_nx1 (تحت). وفروع العمود المركب، اللي مفيهاش انبعاج جانبي التوائي، بتاخد M_p لما تعدّي 16.9/√F_y (10.9) و 58/√F_y (37.44)، وببساطة M_n = M_y = S·F_y لو هي غير مدمجة بس."}},{t:"p",text:{en:"**The LTB curve of a non-compact section.** A flange or a web that is only non-compact buckles locally before the section is fully plastic, so the curve loses its top: the plateau drops from $M_p$ to $M_{nx1}$. Each element is placed between its two limits — $\\lambda$ is its ratio ($c/t_f$ or $d_w/t_w$), $\\lambda_p$ its compact limit, $\\lambda_r$ its non-compact limit — and the weaker element sets the ceiling; a compact element gives $M_p$.",ar:"**منحنى الانبعاج الجانبي لقطاع غير مدمج.** الشفة أو العصب اللي غير مدمج بس بينبعج انبعاج موضعي قبل ما القطاع يبقى لدن بالكامل، فالمنحنى بيفقد راسه: الجزء الأفقي بينزل من $M_p$ لـ $M_{nx1}$. كل عنصر بيتحط بين حدّيه — $\\lambda$ نسبته ($c/t_f$ أو $d_w/t_w$)، و $\\lambda_p$ حد المدمج بتاعه، و $\\lambda_r$ حد غير المدمج — والعنصر الأضعف هو اللي بيحدد السقف؛ والعنصر المدمج بيدّي $M_p$."}},{t:"eq",tex:["M_{nx1} = \\min\\left[\\,M_p - (M_p - M_r)\\dfrac{\\lambda_f - \\lambda_{p,f}}{\\lambda_{r,f} - \\lambda_{p,f}}\\,,\\ \\ M_p - (M_p - M_r)\\dfrac{\\lambda_w - \\lambda_{p,w}}{\\lambda_{r,w} - \\lambda_{p,w}}\\,\\right] \\le M_p","L^{\\prime}_p = L_p + (L_r - L_p)\\,\\dfrac{M_p - M_{nx1}}{M_p - M_r}","L_u \\le L^{\\prime}_p:\\quad M_{nx} = M_{nx1},\\qquad L^{\\prime}_p < L_u \\le L_r:\\quad M_{nx} = C_b\\left[M_p - (M_p - M_r)\\dfrac{L_u - L_p}{L_r - L_p}\\right] \\le M_{nx1}"],caption:{en:"The plateau at M_nx1 runs up to L′_p, the length where the straight line of the inelastic zone (from M_p at L_p to M_r at L_r) comes down to M_nx1; beyond it the same line, and beyond L_r the same elastic branch, both capped at M_nx1. M_r = F_L·S_x (F_L = 0.75F_y rolled, 0.6F_y welded); the moment used in both limit states is φb·M_nx.",ar:"الجزء الأفقي عند M_nx1 بيمتد لحد L′_p، الطول اللي عنده الخط المستقيم بتاع المنطقة غير المرنة (من M_p عند L_p لـ M_r عند L_r) بينزل لـ M_nx1؛ وبعده نفس الخط، وبعد L_r نفس الفرع المرن، والاتنين مقفول عليهم بـ M_nx1. و M_r = F_L·S_x (و F_L = 0.75F_y للمدرفل و 0.6F_y للملحوم)؛ والعزم اللي بيدخل الحالتين الحديتين هو φb·M_nx."}},{t:"p",text:{en:"**Example.** A welded column, flanges 300×12, web 400×8 (h = 424 mm), St 37, $P_u = 40$ t: $A = 104$ cm², $S_x = 1643$ cm³, $Z_x = 1803$ cm³, $r_y = 7.21$ cm. The flange: $c = (30 - 0.8)/2 = 14.6$ cm and $c/t_f = 12.17$, between $15.3/\\sqrt{2.4} = 9.88$ and $21/\\sqrt{2.4} = 13.56$ — non-compact. The web: $h_wt_wF_y = 40\\times0.8\\times2.4 = 76.8$ t, $\\alpha = \\tfrac{1}{2}(40/76.8 + 1) = 0.760$, limit $451.2/(13\\times0.760 - 1) = 50.8 \\ge 400/8 = 50$ — compact, so the flange alone sets the ceiling. $M_p = 1803\\times2.4 = 4328$ t.cm and $M_r = 0.6\\times2.4\\times1643 = 2366$ t.cm; the flange sits at $(12.17 - 9.88)/(13.56 - 9.88) = 0.623$ of the way, so $M_{nx1} = 4328 - 1962\\times0.623 = 3106$ t.cm $= 31.06$ m.t — 28% below $M_p$.",ar:"**مثال.** عمود ملحوم، شفف 300×12 وعصب 400×8 (h = 424 مم)، حديد 37، و $P_u = 40$ طن: $A = 104$ سم²، و $S_x = 1643$ سم³، و $Z_x = 1803$ سم³، و $r_y = 7.21$ سم. الشفة: $c = (30 - 0.8)/2 = 14.6$ سم و $c/t_f = 12.17$، بين $15.3/\\sqrt{2.4} = 9.88$ و $21/\\sqrt{2.4} = 13.56$ — غير مدمجة. العصب: $h_wt_wF_y = 40\\times0.8\\times2.4 = 76.8$ طن، و $\\alpha = \\tfrac{1}{2}(40/76.8 + 1) = 0.760$، والحد $451.2/(13\\times0.760 - 1) = 50.8 \\ge 400/8 = 50$ — مدمج، يبقى الشفة لوحدها هي اللي بتحدد السقف. و $M_p = 1803\\times2.4 = 4328$ طن.سم و $M_r = 0.6\\times2.4\\times1643 = 2366$ طن.سم؛ والشفة واقفة عند $(12.17 - 9.88)/(13.56 - 9.88) = 0.623$ من المسافة، يبقى $M_{nx1} = 4328 - 1962\\times0.623 = 3106$ طن.سم $= 31.06$ م.طن — أقل من $M_p$ بـ 28%."}},{t:"p",text:{en:"The LTB curve of this column: $L_p = 80\\times7.21/\\sqrt{2.4} = 372$ cm, $r_T = 8.08$ cm, $X = 0.980$, $F_L = 1.44$ t/cm², $L_r = 1150$ cm, and the plateau lasts up to $L^{\\prime}_p = 372 + (1150 - 372)\\times0.623 = 856$ cm. Over $L_u = 6$ m the straight line would still give 37.53 m.t, but the column keeps only $M_{nx1} = 31.06$ m.t. Over $L_u = 10$ m with $C_b = 1$ the line governs: $4328 - 1962\\times(1000 - 372)/(1150 - 372) = 2744$ t.cm $= 27.44$ m.t. With $C_b = 1.3$ the line rises to 35.67 m.t — and is cut back to 31.06: no moment gradient lifts a non-compact section above its own ceiling.",ar:"منحنى الانبعاج الجانبي للعمود ده: $L_p = 80\\times7.21/\\sqrt{2.4} = 372$ سم، و $r_T = 8.08$ سم، و $X = 0.980$، و $F_L = 1.44$ طن/سم²، و $L_r = 1150$ سم، والجزء الأفقي بيمتد لحد $L^{\\prime}_p = 372 + (1150 - 372)\\times0.623 = 856$ سم. على $L_u = 6$ م الخط المستقيم كان لسه هيدّي 37.53 م.طن، لكن العمود بياخد $M_{nx1} = 31.06$ م.طن بس. وعلى $L_u = 10$ م و $C_b = 1$ الخط هو اللي بيحكم: $4328 - 1962\\times(1000 - 372)/(1150 - 372) = 2744$ طن.سم $= 27.44$ م.طن. ومع $C_b = 1.3$ الخط بيطلع لـ 35.67 م.طن — وبيتقص تاني لـ 31.06: مفيش تدرج عزم بيرفع قطاع غير مدمج فوق السقف بتاعه."}},{t:"quiz",q:{kind:"num",q:{en:"P_u = 0.3·h_w·t_w·F_y. α?",ar:"P_u = 0.3·h_w·t_w·F_y. قيمة α؟"},answer:.65,tol:.003,explain:{en:"$\\tfrac{1}{2}(0.3 + 1) = 0.65$: 65% of the web is compressed.",ar:"$\\tfrac{1}{2}(0.3 + 1) = 0.65$: 65% من العصب مضغوط."}}}]},{id:"bracing",title:{en:"The actual unbraced length: struts and knee braces",ar:"الطول الفعلي غير المثبت: الستراتات والركب"},blocks:[{t:"p",text:{en:"The side girts are bolted to the **outer** flange of the column, so that flange is held every 1.5–2 m. The **inner** flange is free between the base, the truss and whatever reaches it. $L_{u,act}$ is the length of the compression flange between two points that really hold it:",ar:"المدادات الجانبية (Side girts) متربطة في الشفة **الخارجية** للعمود، فالشفة دي ممسوكة كل 1.5–2 م. أما الشفة **الداخلية** فحرة بين القاعدة والجمالون وأي حاجة بتوصلها. و $L_{u,act}$ هو طول الشفة المضغوطة بين نقطتين ماسكينها بجد:"}},{t:"steps",items:[{en:"No intermediate support: $L_u = h$, the height of the column.",ar:"مفيش سند في النص: $L_u = h$، ارتفاع العمود."},{en:"A **horizontal strut** of the vertical bracing at mid-height holds the whole section: $L_u = h/2$ and $L_{b,out} = h/2$.",ar:"**ستراتة أفقية** في الشكالات الرأسية في نص الارتفاع بتمسك القطاع كله: $L_u = h/2$ و $L_{b,out} = h/2$."},{en:"**Knee braces** — an angle (L60×60×6, say) from a side girt to the inner flange — at mid-height: $L_u = h/2$, but $L_{b,out}$ stays $h$: a girt is not a support of the whole column.",ar:"**الركب (Knee braces)** — زاوية (L60×60×6 مثلًا) من مدادة جانبية للشفة الداخلية — في نص الارتفاع: $L_u = h/2$، لكن $L_{b,out}$ بيفضل $h$: المدادة مش سند للعمود كله."},{en:"A moment that reverses at a height $a$ (fixed base): the compressed flange changes side — the **inner** flange above the point of zero moment, the **outer** flange below it. The upper section (1-1) takes $L_u = h - a$; the section at the base (2-2) takes $L_b = a$, on the outer flange.",ar:"عزم بيعكس إشارته عند ارتفاع $a$ (قاعدة ثابتة): الشفة المضغوطة بتغيّر ناحيتها — الشفة **الداخلية** فوق نقطة العزم الصفر، والشفة **الخارجية** تحتها. القطاع العلوي (1-1) بياخد $L_u = h - a$؛ والقطاع عند القاعدة (2-2) بياخد $L_b = a$، على الشفة الخارجية."},{en:"The same reversal with a **strut at mid-height** (the reversal below it): section 1-1 now takes $L_b = h/2$, while section 2-2 keeps $L_b = a$ on the outer flange.",ar:"نفس العكس ومعاه **ستراتة في نص الارتفاع** (ونقطة العكس تحتها): القطاع 1-1 بقى بياخد $L_b = h/2$، والقطاع 2-2 بيفضل $L_b = a$ على الشفة الخارجية."},{en:"**One length for the column of a fixed-base trussed frame**: the inner flange is compressed over the upper length $L_1$, from the lower chord down to the point of zero moment (or down to a strut that holds it sooner), and the outer flange over $L_{u,out}$, from there down to the base. The column is checked with $L_{u,act}$ = **the larger of $L_1$ and $L_{u,out}$**.",ar:"**طول واحد لعمود إطار بجمالون ركائزه ثابتة**: الشفة الداخلية مضغوطة على الطول العلوي $L_1$، من الوتر السفلي لحد نقطة العزم الصفر (أو لحد ستراتة ماسكاها قبلها)، والشفة الخارجية على $L_{u,out}$، من هناك لحد القاعدة. والعمود بيتراجع بـ $L_{u,act}$ = **الأكبر من $L_1$ و $L_{u,out}$**."},{en:"A **Fink truss** rests on a hinge at the top of the column, so the column stands as a cantilever — **its base must be fixed**. With a strut at mid-height, the lower half takes $L_{u,act} = L_{u,out} = h/2$.",ar:"**جمالون فينك** قاعد على مفصل فوق العمود، فالعمود واقف ككابولي — **لازم قاعدته تبقى ثابتة**. ومع ستراتة في نص الارتفاع، النص السفلي بياخد $L_{u,act} = L_{u,out} = h/2$."},{en:"A cantilever shed has no side girts, hence no knee braces: add a horizontal member in the vertical bracing, $L_b = h/2 = L_{b,out}$.",ar:"الهنجر الكابولي ملوش مدادات جانبية، يبقى مفيش ركب: زوّد عضو أفقي في الشكالات الرأسية، و $L_b = h/2 = L_{b,out}$."}]},{t:"table",head:[{en:"Part of the knee brace",ar:"جزء الركبة"},{en:"Detail",ar:"التفصيلة"}],rows:[[{en:"side girt",ar:"المدادة الجانبية"},{en:"a channel along the wall, on the outer flange, fixed to it by a cleat with 4 bolts",ar:"مجرى ماشي مع الحائط، على الشفة الخارجية، متثبت فيها بزاوية تثبيت (Cleat) بـ 4 مسامير"}],[{en:"braces",ar:"الركب"},{en:"two angles L60×60×6, one on each side of the column, at about 45° in plan",ar:"زاويتين L60×60×6، واحدة على كل ناحية من العمود، بزاوية حوالي 45° في المسقط الأفقي"}],[{en:"at the girt",ar:"عند المدادة"},{en:"one bolt per angle",ar:"مسمار واحد لكل زاوية"}],[{en:"at the column",ar:"عند العمود"},{en:"one bolt per angle to a gusset plate welded on the inner flange",ar:"مسمار واحد لكل زاوية في لوح وصلة (Gusset) ملحوم على الشفة الداخلية"}],[{en:"in elevation",ar:"في الواجهة"},{en:"the sheeting outside, the girt on the outer flange, the brace rising from the girt to the plate on the inner flange, at mid-height",ar:"الصاج من برّه، والمدادة على الشفة الخارجية، والركبة طالعة من المدادة للوح اللي على الشفة الداخلية، في نص الارتفاع"}]],caption:{en:"The knee brace in plan and elevation. It holds the inner, compressed flange at mid-height — L_u,act = h/2 — but the girt only spans between frames, so L_b,out does not change.",ar:"الركبة في المسقط الأفقي والواجهة. بتمسك الشفة الداخلية المضغوطة في نص الارتفاع — L_u,act = h/2 — لكن المدادة بتعدّي بين الإطارات وبس، فـ L_b,out مش بيتغير."}},{t:"note",tone:"tip",text:{en:"Where to put horizontal struts in the vertical bracing: at the levels of the truss chords (the lower chord and the eaves); along the rafter of a portal frame; at the crane-girder level — the girder holds the column, but the braking force needs a real strut and bracing at that level; at a mezzanine floor or any beam that frames into the column; and at mid-height whenever the clear height is 6 m or more.",ar:"تحط الستراتات الأفقية في الشكالات الرأسية فين: عند مناسيب أوتار الجمالون (الوتر السفلي والراس)؛ وعلى طول الـ Rafter في الإطار البوابي؛ وعند منسوب كمرة الونش — الكمرة بتمسك العمود، لكن قوة الفرامل محتاجة ستراتة وشكالات حقيقية عند المنسوب ده؛ وعند دور ميزانين أو أي كمرة بتتوصل في العمود؛ وفي نص الارتفاع كل ما الارتفاع الصافي يوصل 6 م أو أكتر."}},{t:"p",text:{en:"**Example.** A trussed frame with hinged bases, IPE 360 columns 7 m to the lower chord, $h_1 = 1.5$ m, $P_u = 10$ t, a first-order wind moment of 16 m.t ($B_2 = 1.077$, $M_u = 17.2$ m.t). Nothing in between: $\\lambda_y = 700/3.79 = 184.7 > 180$, and over 7 m the flange buckles elastically ($M_{nx} = 22.97$ m.t): $LS_2 = 1.22$. Knee braces at 3.5 m cut $L_u$ to 3.5 m ($C_b = 1.30$ for the upper half, $M_{nx} = M_p$), but $\\lambda_y$ is still 184.7 and $LS_2 = 1.12$. A **strut** at 3.5 m does both: $\\lambda_y = 92.3$, $\\phi P_{ny} = 86.7$ t, $LS_2 = 0.80$ and $LS_1 = 0.90$ — it passes.",ar:"**مثال.** إطار بجمالون وركائز مفصلية، أعمدة IPE 360 طولها 7 م لحد الوتر السفلي، و $h_1 = 1.5$ م، و $P_u = 10$ طن، وعزم رياح من الدرجة الأولى 16 م.طن ($B_2 = 1.077$، و $M_u = 17.2$ م.طن). من غير أي حاجة في النص: $\\lambda_y = 700/3.79 = 184.7 > 180$، وعلى 7 م الشفة بتنبعج انبعاج مرن ($M_{nx} = 22.97$ م.طن): $LS_2 = 1.22$. الركب عند 3.5 م بتقصّر $L_u$ لـ 3.5 م ($C_b = 1.30$ للنص العلوي، و $M_{nx} = M_p$)، لكن $\\lambda_y$ لسه 184.7 و $LS_2 = 1.12$. أما **الستراتة** عند 3.5 م فبتعمل الاتنين: $\\lambda_y = 92.3$، و $\\phi P_{ny} = 86.7$ طن، و $LS_2 = 0.80$ و $LS_1 = 0.90$ — بيعدّي."}},{t:"p",text:{en:"**Example: a moment that reverses.** A column of a fixed-base trussed frame, 7.5 m to the lower chord; under wind its moment changes sign 2.5 m above the base. The inner flange is compressed over $L_1 = 7.5 - 2.5 = 5.0$ m, the outer flange over $L_{u,out} = a = 2.5$ m, so $L_{u,act} = \\max(5.0,\\ 2.5) = 5.0$ m. The clear height passes 6 m, so a strut goes in at mid-height, 3.75 m: section 1-1 now takes $L_b = 7.5/2 = 3.75$ m, section 2-2 keeps $L_b = a = 2.5$ m on the outer flange, and the column is checked with $L_{u,act} = \\max(3.75,\\ 2.5) = 3.75$ m.",ar:"**مثال: عزم بيعكس إشارته.** عمود في إطار بجمالون ركائزه ثابتة، طوله 7.5 م لحد الوتر السفلي؛ وتحت الرياح عزمه بيغيّر إشارته على ارتفاع 2.5 م من القاعدة. الشفة الداخلية مضغوطة على $L_1 = 7.5 - 2.5 = 5.0$ م، والخارجية على $L_{u,out} = a = 2.5$ م، يبقى $L_{u,act} = \\max(5.0,\\ 2.5) = 5.0$ م. والارتفاع الصافي عدّى 6 م، يبقى لازم ستراتة في نص الارتفاع، عند 3.75 م: القطاع 1-1 بقى بياخد $L_b = 7.5/2 = 3.75$ م، والقطاع 2-2 بيفضل $L_b = a = 2.5$ م على الشفة الخارجية، والعمود بيتراجع بـ $L_{u,act} = \\max(3.75,\\ 2.5) = 3.75$ م."}},{t:"lab",lab:"buckling",height:480,props:{preset:"bcBracing",missions:s,defaultTab:"inputs"},caption:{en:"The 7 m IPE 360 column of the example: add knee braces, then a strut, and follow the point on the LTB curve and the elevations below.",ar:"عمود الـ IPE 360 بطول 7 م بتاع المثال: ركّب ركب، وبعدين ستراتة، وتابع النقطة على منحنى الانبعاج الجانبي والواجهات اللي تحت."}},{t:"quiz",q:{kind:"tf",q:{en:"Knee braces from the side girts shorten the out-of-plane buckling length L_b,out of the column.",ar:"الركب اللي من المدادات الجانبية بتقصّر طول الانبعاج خارج المستوى L_b,out للعمود."},answer:!1,explain:{en:"They hold the inner flange against lateral–torsional buckling only; L_b,out needs a strut of the vertical bracing.",ar:"بتمسك الشفة الداخلية ضد الانبعاج الجانبي الالتوائي بس؛ و L_b,out محتاج ستراتة في الشكالات الرأسية."}}}]},{id:"bracket",title:{en:"Double cantilevers and columns with brackets",ar:"الكوابيل من الناحيتين والأعمدة اللي عليها كوابيل"},blocks:[{t:"p",text:{en:"A column that carries loads on **both** sides — a double-cantilever car shed, a column between two crane runways, a bracket for a mezzanine beam on one side and a crane girder on the other — has two load cases, because the live load may be on one side only:",ar:"العمود اللي شايل أحمال من **الناحيتين** — مظلة عربيات كابولي من الناحيتين، أو عمود بين مجريين أوناش، أو كابولي لكمرة ميزانين من ناحية وكمرة ونش من الناحية التانية — ليه حالتين تحميل، لأن الحمل الحي ممكن يبقى على ناحية واحدة بس:"}},{t:"steps",items:[{en:"**Maximum normal force** (case 1): the full load (dead + live) on both sides — the largest normal force N₁, with a small moment M₁ or none.",ar:"**أقصى قوة عمودية** (الحالة 1): الحمل الكامل (ميت + حي) على الناحيتين — أكبر قوة عمودية N₁، مع عزم صغير M₁ أو مفيش."},{en:"**Maximum moment** (case 2): the full load on one side and the dead load alone on the other — the largest moment M₂ with a smaller N₂.",ar:"**أقصى عزم** (الحالة 2): الحمل الكامل على ناحية والحمل الميت بس على التانية — أكبر عزم M₂ مع N₂ أصغر."},{en:"Both cases act on **the same cut**, at the foot of the column, where N and M are largest. Design the section on case 2 — M₂ with the N₂ that goes with it — then check it under case 1, N₁ with M₁.",ar:"الحالتين شغالين على **نفس القطاع**، عند رجل العمود، مكان ما N و M أكبر حاجة. صمّم القطاع على الحالة 2 — M₂ مع الـ N₂ اللي معاه — وبعدين راجعه تحت الحالة 1، N₁ مع M₁."}]},{t:"p",text:{en:"**Example.** A column between two crane bays carries a bracket on each side at 0.45 m from its axis; each bracket: dead 3 t, live 9 t. Full side: $1.2\\times3 + 1.6\\times9 = 18.0$ t, dead side: $1.2\\times3 = 3.6$ t. **Case 1 (largest N):** $N = 2\\times18.0 = 36.0$ t, $M = 0$. **Case 2 (largest M):** $N = 18.0 + 3.6 = 21.6$ t, $M = (18.0 - 3.6)\\times0.45 = 6.48$ m.t. With a factored roof reaction of 8 t on top, the cut at the foot of the column takes $N_2 = 8 + 21.6 = 29.6$ t with $M_2 = 6.48$ m.t in case 2 — the section is designed on it — and $N_1 = 8 + 36.0 = 44$ t with $M_1 = 0$ in case 1, which then checks it.",ar:"**مثال.** عمود بين باكيتين أوناش شايل كابولي على كل ناحية على بعد 0.45 م من محوره؛ كل كابولي: ميت 3 طن وحي 9 طن. الناحية المحمّلة بالكامل: $1.2\\times3 + 1.6\\times9 = 18.0$ طن، والناحية اللي عليها الميت بس: $1.2\\times3 = 3.6$ طن. **الحالة 1 (أكبر N):** $N = 2\\times18.0 = 36.0$ طن، و $M = 0$. **الحالة 2 (أكبر M):** $N = 18.0 + 3.6 = 21.6$ طن، و $M = (18.0 - 3.6)\\times0.45 = 6.48$ م.طن. ولو فوق العمود رد فعل سقف مضروب 8 طن، يبقى القطاع عند رجل العمود واخد $N_2 = 8 + 21.6 = 29.6$ طن مع $M_2 = 6.48$ م.طن في الحالة 2 — وعليها بنصمّم القطاع — و $N_1 = 8 + 36.0 = 44$ طن مع $M_1 = 0$ في الحالة 1، وبيها بنراجعه بعد كده."}},{t:"p",text:{en:"**A column with a bracket.** In a trussed frame on hinged bases, a crane bracket on the inner side changes both diagrams at its level. The normal force steps up there: $N_2$ above the bracket (the roof alone), $N_1$ below it (roof + crane). The moment, zero at the hinged base, grows up the column and is largest at the lower chord ($M_2$), smaller at the bracket ($M_1$). So two sections are checked: **2-2 at the top**, just under the truss, with $M_2$ and $N_2$ — the section is **designed** on it — and **1-1 at the bracket**, with $M_1$ and the larger $N_1$ — it is **checked** there.",ar:"**عمود عليه كابولي.** في إطار بجمالون على ركائز مفصلية، كابولي الونش على الناحية الداخلية بيغيّر المنحنيين عند منسوبه. القوة العمودية بتنط هناك: $N_2$ فوق الكابولي (السقف لوحده)، و $N_1$ تحته (السقف + الونش). والعزم، صفر عند القاعدة المفصلية، بيكبر لفوق وبيبقى أكبر حاجة عند الوتر السفلي ($M_2$)، وأصغر عند الكابولي ($M_1$). يبقى بنراجع قطاعين: **2-2 فوق**، تحت الجمالون على طول، بـ $M_2$ و $N_2$ — وعليه **بنصمّم** القطاع — و**1-1 عند الكابولي**، بـ $M_1$ و $N_1$ الأكبر — وهناك **بنراجعه**."}},{t:"p",text:{en:"**Example.** A trussed frame on hinged bases: the column is 5.5 m to the lower chord, the truss 1.5 m deep, so $L_{b,in} = 2\\,(5.5 + 0.75) = 12.5$ m; a crane bracket at 4.0 m with a strut of the vertical bracing at that level, so $L_{b,out} = 4.0$ m. A second-order analysis gives $M_2 = 12$ m.t with $N_2 = 5$ t under the truss and $M_1 = 7$ m.t with $N_1 = 20$ t at the bracket. **Design 2-2:** $S_x = 1200/(0.9\\times0.85\\times2.4) = 653.6$ cm³ → IPE 330. Its inner flange is held at the lower chord and at the bracket, $L_u = 1.5$ m $< L_p = 1.83$ m: $M_{nx} = M_p = 804\\times2.4 = 1930$ t.cm, $\\phi_bM_{nx} = 16.40$ m.t. $\\lambda_x = 1250/13.7 = 91.2$ gives $\\phi P_{nx} = 75.7$ t; $\\lambda_y = 400/3.55 = 112.7$ gives $\\phi P_{ny} = 53.0$ t. $5/75.7 = 0.066 < 0.2$: $LS_1 = 0.033 + 12/16.40 = 0.76$ and $LS_2 = 5/53.0 + (12/16.40)^2 = 0.63$. **Check 1-1:** below the bracket $L_u = 4.0$ m, the hinged base gives $\\alpha = 0$ and $C_b = 1.75$, and LTB allows 27.3 m.t — more than $M_p$. $20/75.7 = 0.264 \\ge 0.2$: $LS_1 = 0.264 + \\tfrac{8}{9}\\times7/16.40 = 0.64$ and $LS_2 = 20/53.0 + (7/16.40)^2 = 0.56$. The top section governs, as it should.",ar:"**مثال.** إطار بجمالون على ركائز مفصلية: العمود 5.5 م لحد الوتر السفلي، والجمالون عمقه 1.5 م، يبقى $L_{b,in} = 2\\,(5.5 + 0.75) = 12.5$ م؛ وكابولي ونش عند 4.0 م ومعاه ستراتة في الشكالات الرأسية عند نفس المنسوب، يبقى $L_{b,out} = 4.0$ م. التحليل من الدرجة التانية بيدّي $M_2 = 12$ م.طن مع $N_2 = 5$ طن تحت الجمالون، و $M_1 = 7$ م.طن مع $N_1 = 20$ طن عند الكابولي. **تصميم 2-2:** $S_x = 1200/(0.9\\times0.85\\times2.4) = 653.6$ سم³ ← IPE 330. شفته الداخلية ممسوكة عند الوتر السفلي وعند الكابولي، و $L_u = 1.5$ م $< L_p = 1.83$ م: $M_{nx} = M_p = 804\\times2.4 = 1930$ طن.سم، و $\\phi_bM_{nx} = 16.40$ م.طن. و $\\lambda_x = 1250/13.7 = 91.2$ بتدّي $\\phi P_{nx} = 75.7$ طن؛ و $\\lambda_y = 400/3.55 = 112.7$ بتدّي $\\phi P_{ny} = 53.0$ طن. و $5/75.7 = 0.066 < 0.2$: $LS_1 = 0.033 + 12/16.40 = 0.76$ و $LS_2 = 5/53.0 + (12/16.40)^2 = 0.63$. **مراجعة 1-1:** تحت الكابولي $L_u = 4.0$ م، والقاعدة المفصلية بتدّي $\\alpha = 0$ و $C_b = 1.75$، والانبعاج الجانبي بيسمح بـ 27.3 م.طن — أكتر من $M_p$. و $20/75.7 = 0.264 \\ge 0.2$: $LS_1 = 0.264 + \\tfrac{8}{9}\\times7/16.40 = 0.64$ و $LS_2 = 20/53.0 + (7/16.40)^2 = 0.56$. القطاع العلوي هو اللي بيحكم، زي ما متوقع."}},{t:"quiz",q:{kind:"num",q:{en:"Brackets on both sides at 0.5 m from the axis; each: dead 2 t, live 5 t. The factored moment of the maximum-moment case (m.t)?",ar:"كوابيل على الناحيتين على بعد 0.5 م من المحور؛ كل واحد: ميت 2 طن وحي 5 طن. العزم المضروب لحالة أقصى عزم (م.طن)؟"},answer:4,tol:.003,unit:"m.t",explain:{en:"Full side $2.4 + 8.0 = 10.4$ t, dead side $2.4$ t: $(10.4 - 2.4)\\times0.5 = 4.0$ m.t.",ar:"الناحية الكاملة $2.4 + 8.0 = 10.4$ طن، والناحية الميتة $2.4$ طن: $(10.4 - 2.4)\\times0.5 = 4.0$ م.طن."}}}]},{id:"example",title:{en:"A complete design, step by step",ar:"تصميم كامل خطوة بخطوة"},blocks:[{t:"steps",items:[{en:"The frame and the actions: $P_u$, $M_{nt}$, $M_{lt}$ from the analysis; the buckling lengths $L_{b,in}$, $L_{b,out}$ and $L_{u,act}$.",ar:"الإطار والأحمال: $P_u$ و $M_{nt}$ و $M_{lt}$ من التحليل؛ وأطوال الانبعاج $L_{b,in}$ و $L_{b,out}$ و $L_{u,act}$."},{en:"The amplification $B_1$, $B_2$ (skip it if the analysis was second-order) and a first size from $S_x$ (factor 0.9 for a light normal force, down to 0.7 for a heavy one).",ar:"التكبير $B_1$ و $B_2$ (سيبه لو التحليل من الدرجة التانية) وأول مقاس من $S_x$ (معامل 0.9 لقوة عمودية خفيفة، لحد 0.7 للتقيلة)."},{en:"The class of the section under N + M: the flanges, the web by α and ψ.",ar:"تصنيف القطاع تحت N + M: الشفف، والعصب بـ α و ψ."},{en:"$P_{nx}$ and $P_{ny}$ from the column curve ($\\lambda \\le 180$ in both directions); $M_{nx}$ — the moment of the section reduced by LTB over $L_{u,act}$ with $C_b$, the same value for both limit states; $C_m$ from the diagram.",ar:"$P_{nx}$ و $P_{ny}$ من منحنى الأعمدة ($\\lambda \\le 180$ في الاتجاهين)؛ و $M_{nx}$ — عزم القطاع ناقص بالانبعاج الجانبي على $L_{u,act}$ مع $C_b$، نفس القيمة للحالتين الحديتين؛ و $C_m$ من المنحنى."},{en:"Limit states 1 and 2; change the section, or the bracing, and repeat.",ar:"الحالتين الحديتين 1 و 2؛ غيّر القطاع أو التثبيت وكرّر."}]},{t:"p",text:{en:"**The frame.** A trussed frame with **fixed** bases, columns 6.0 m to the lower chord, truss 1.8 m deep at the column, St 37; $P_u = 30$ t and a first-order wind moment $M_{lt} = 16$ m.t. $L_{b,in} = 1.2\\,(6.0 + 0.9) = 8.28$ m; $L_{b,out} = \\max(1.8,\\ 6.0) = 6.0$ m; no struts or knee braces. With $\\alpha = +0.5$ the moment changes sign $6.0/3 = 2.0$ m above the base: the inner flange is compressed over $L_1 = 4.0$ m, the outer one over 2.0 m, so $L_{u,act} = \\max(4.0,\\ 2.0) = 4.0$ m. The checks below take $L_{u,act} = 4.0$ m, as the lab does; the whole 6.0 m would be on the safe side, and $M_{nx}$ comes out as $M_p$ either way. $C_b = 2.3$, $C_m = 0.85$. **First size:** guess $B_2 \\approx 1.1$, $M_u \\approx 17.6$ m.t, $S_x = 1760/1.632 = 1078$ cm³ → IPE 400.",ar:"**الإطار.** إطار بجمالون وركائز **ثابتة**، الأعمدة 6.0 م لحد الوتر السفلي، والجمالون عمقه 1.8 م عند العمود، حديد 37؛ و $P_u = 30$ طن وعزم رياح من الدرجة الأولى $M_{lt} = 16$ م.طن. $L_{b,in} = 1.2\\,(6.0 + 0.9) = 8.28$ م؛ و $L_{b,out} = \\max(1.8,\\ 6.0) = 6.0$ م؛ ومفيش ستراتات ولا ركب. ومع $\\alpha = +0.5$ العزم بيغيّر إشارته على ارتفاع $6.0/3 = 2.0$ م من القاعدة: الشفة الداخلية مضغوطة على $L_1 = 4.0$ م، والخارجية على 2.0 م، يبقى $L_{u,act} = \\max(4.0,\\ 2.0) = 4.0$ م. المراجعات اللي جاية بتاخد $L_{u,act} = 4.0$ م، زي المعمل؛ والـ 6.0 م كلهم كانوا هيبقوا في ناحية الأمان، و $M_{nx}$ بيطلع $M_p$ في الحالتين. و $C_b = 2.3$، و $C_m = 0.85$. **أول مقاس:** نخمّن $B_2 \\approx 1.1$، و $M_u \\approx 17.6$ م.طن، و $S_x = 1760/1.632 = 1078$ سم³ ← IPE 400."}},{t:"p",text:{en:"**IPE 400 fails.** Its own $B_2 = 1.045$ gives $M_u = 16.72$ m.t, but out of plane $\\lambda_y = 600/3.95 = 151.9$, $\\lambda_c = 1.63$, $F_{cr} = 0.582$ t/cm², $\\phi P_{ny} = 39.3$ t: $LS_2 = 30/39.3 + (16.72/26.66)^2 = 0.76 + 0.39 = 1.16$. The normal force alone takes three quarters of the weak axis — the HEB rule of thumb says it: a 6 m weak axis under 30 t needs a wider section.",ar:"**الـ IPE 400 بيقع.** الـ $B_2$ بتاعه $= 1.045$ بتدّي $M_u = 16.72$ م.طن، لكن خارج المستوى $\\lambda_y = 600/3.95 = 151.9$، و $\\lambda_c = 1.63$، و $F_{cr} = 0.582$ طن/سم²، و $\\phi P_{ny} = 39.3$ طن: $LS_2 = 30/39.3 + (16.72/26.66)^2 = 0.76 + 0.39 = 1.16$. القوة العمودية لوحدها واكلة تلات أرباع المحور الضعيف — وقاعدة الـ HEB بتقولها: محور ضعيف طوله 6 م تحت 30 طن محتاج قطاع أعرض."}},{t:"p",text:{en:"**HEB 240** ($A = 106$ cm², $r_x = 10.3$, $r_y = 6.08$ cm, $S_x = 938$, $Z_x = 1053$ cm³): $P_{e2} = 340.4$ t, $B_2 = 1.097$, $M_u = 17.55$ m.t. Class: $c/t_f = 9.40/1.70 = 5.53 \\le 10.9$; $h_wt_wF_y = 49.4$ t, $\\alpha = 0.803$, limit 47.8 against $d_w/t_w = 16.4$ — compact. In plane: $\\lambda_x = 828/10.3 = 80.4$, $F_{cr} = 1.710$ t/cm², $\\phi P_{nx} = 145.0$ t. Out of plane: $\\lambda_y = 600/6.08 = 98.7$, $F_{cr} = 1.361$ t/cm², $\\phi P_{ny} = 115.4$ t. $M_p = 25.27$ m.t, $\\phi_bM_p = 21.48$ m.t; $L_p = 3.14$ m $< L_{u,act} = 4.0$ m $< L_r = 13.56$ m and $C_b = 2.3$ lift the LTB value above $M_p$: $M_{nx} = M_p$. $P_u/\\phi P_{nx} = 0.207 \\ge 0.2$: $LS_1 = 0.207 + \\tfrac{8}{9}\\times17.55/21.48 = 0.93$; $LS_2 = 30/115.4 + (17.55/21.48)^2 = 0.26 + 0.67 = 0.93$. **HEB 240 it is.**",ar:"**HEB 240** ($A = 106$ سم²، و $r_x = 10.3$، و $r_y = 6.08$ سم، و $S_x = 938$، و $Z_x = 1053$ سم³): $P_{e2} = 340.4$ طن، و $B_2 = 1.097$، و $M_u = 17.55$ م.طن. التصنيف: $c/t_f = 9.40/1.70 = 5.53 \\le 10.9$؛ و $h_wt_wF_y = 49.4$ طن، و $\\alpha = 0.803$، والحد 47.8 قصاد $d_w/t_w = 16.4$ — مدمج. داخل المستوى: $\\lambda_x = 828/10.3 = 80.4$، و $F_{cr} = 1.710$ طن/سم²، و $\\phi P_{nx} = 145.0$ طن. خارج المستوى: $\\lambda_y = 600/6.08 = 98.7$، و $F_{cr} = 1.361$ طن/سم²، و $\\phi P_{ny} = 115.4$ طن. و $M_p = 25.27$ م.طن، و $\\phi_bM_p = 21.48$ م.طن؛ و $L_p = 3.14$ م $< L_{u,act} = 4.0$ م $< L_r = 13.56$ م مع $C_b = 2.3$ بيطلّعوا قيمة الانبعاج الجانبي فوق $M_p$: $M_{nx} = M_p$. و $P_u/\\phi P_{nx} = 0.207 \\ge 0.2$: $LS_1 = 0.207 + \\tfrac{8}{9}\\times17.55/21.48 = 0.93$؛ و $LS_2 = 30/115.4 + (17.55/21.48)^2 = 0.26 + 0.67 = 0.93$. **يبقى HEB 240.**"}},{t:"lab",lab:"buckling",height:480,props:{preset:"bcFrames",missions:o,defaultTab:"steps"},caption:{en:"The example in the lab, with its solution step by step: switch to IPE 400 and to HEB 220 and read which check fails.",ar:"المثال في المعمل بحله خطوة بخطوة: حوّل لـ IPE 400 ولـ HEB 220 واقرا أنهي مراجعة بتقع."}},{t:"quiz",q:{kind:"mcq",q:{en:"Why does the IPE 400 fail in this example although its S_x passes the pre-sizing?",ar:"ليه الـ IPE 400 بيقع في المثال ده مع إن S_x بتاعه عدّى أول مقاس؟"},options:[{en:"its weak axis over 6 m gives a small P_ny (λ_y = 152), so LS₂ exceeds 1",ar:"محوره الضعيف على 6 م بيدّي P_ny صغيرة (λ_y = 152)، فـ LS₂ بتعدّي 1"},{en:"its plastic moment is too small",ar:"عزمه اللدن صغير"},{en:"its web is slender under N + M",ar:"عصبه نحيف تحت N + M"}],answer:0,explain:{en:"LS₁ is only 0.77: the section has moment to spare, but 30 t on a 6 m weak axis uses 76% of the out-of-plane capacity before the moment term.",ar:"LS₁ بس 0.77: القطاع عنده عزم زيادة، لكن 30 طن على محور ضعيف 6 م بيستهلكوا 76% من المقاومة خارج المستوى قبل حد العزم."}}}]},{id:"apply",title:{en:"Your workshop: the columns as beam-columns",ar:"ورشتك: الأعمدة كأعمدة تحت حمل وعزم"},blocks:[{t:"p",text:{en:"The workshop columns are **HEB 300**, 6.0 m high, fixed in their footings, with the triangular truss pinned on top. Across the building each column is a cantilever tied to the other by the truss: $L_{b,in} = 2.1\\times6.0 = 12.6$ m. Along it the crane girder holds the column at 4.6 m: $L_{b,out} = 4.6$ m — and since the girder sits on the inner side, it also holds the inner flange: $L_u = 4.6$ m. Per column: dead load 15 kN from the truss plus 6.89 kN of own weight, roof live load 15 kN.",ar:"أعمدة الورشة **HEB 300**، ارتفاعها 6.0 م، ثابتة في قواعدها، والجمالون المثلث مفصلي فوقها. بعرض المبنى كل عمود كابولي مربوط بالتاني عن طريق الجمالون: $L_{b,in} = 2.1\\times6.0 = 12.6$ م. وبطول المبنى كمرة الونش ماسكة العمود عند 4.6 م: $L_{b,out} = 4.6$ م — ولأن الكمرة قاعدة على الناحية الداخلية، فهي كمان ماسكة الشفة الداخلية: $L_u = 4.6$ م. لكل عمود: حمل ميت 15 kN من الجمالون و 6.89 kN وزن العمود نفسه، وحمل حي للسقف 15 kN."}},{t:"p",text:{en:"**The wind.** The wall pushes the windward column with $P_1 = 3.27$ kN/m and sucks the leeward one outwards with 2.04 kN/m — both to the same side. The roof is sucked up: 31.9 kN in all, which lifts each column by 17.6 kN (windward) and 14.2 kN (leeward), with a small horizontal resultant of 1.96 kN towards the windward side. The truss makes the two tops move together: it pulls the windward column back with 2.36 kN and pushes the other with 0.40 kN, and the base moments are 44.66 and 39.14 kN·m.",ar:"**الرياح.** الحائط بيزق العمود المواجه بـ $P_1 = 3.27$ kN/م وبيسحب العمود الخلفي لبرّه بـ 2.04 kN/م — الاتنين لنفس الناحية. والسقف بيتسحب لفوق: 31.9 kN في المجموع، بترفع كل عمود 17.6 kN (المواجه) و 14.2 kN (الخلفي)، مع محصلة أفقية صغيرة 1.96 kN ناحية المواجه. والجمالون بيخلّي الراسين يتحركوا مع بعض: بيشد العمود المواجه لورا بـ 2.36 kN وبيزق التاني بـ 0.40 kN، وعزوم القاعدتين 44.66 و 39.14 kN·m."}},{t:"p",text:{en:"**The governing case** is $1.2D + 1.3W + 0.5L_r$ on the windward column: $N = 1.2\\times21.89 + 0.5\\times15 - 1.3\\times17.63 = 10.84$ kN $= 1.10$ t and $M = 1.3\\times44.66 = 58.05$ kN·m $= 5.92$ m.t. The frame sways ($K = 2.1$): $P_{e2} = 328.6$ t per column, $\\Sigma P_u = 2.66$ t, $B_2 = 1.004$ — a light roof hardly amplifies — so $M_u = 5.94$ m.t, $P_u = 1.10$ t. The wind bends the column along a curve: $C_b = 2.14$ from the quarter points of the segment below the crane girder; $C_m = 0.85$.",ar:"**الحالة الحاكمة** هي $1.2D + 1.3W + 0.5L_r$ على العمود المواجه: $N = 1.2\\times21.89 + 0.5\\times15 - 1.3\\times17.63 = 10.84$ kN $= 1.10$ طن و $M = 1.3\\times44.66 = 58.05$ kN·m $= 5.92$ م.طن. الإطار بيتحرك جانبيًا ($K = 2.1$): $P_{e2} = 328.6$ طن لكل عمود، و $\\Sigma P_u = 2.66$ طن، و $B_2 = 1.004$ — السقف الخفيف تقريبًا مش بيكبّر — يبقى $M_u = 5.94$ م.طن، و $P_u = 1.10$ طن. والرياح بتحني العمود على منحنى: $C_b = 2.14$ من نقط الأرباع للجزء اللي تحت كمرة الونش؛ و $C_m = 0.85$."}},{t:"p",text:{en:"**The checks.** Compact: flange 6.18, web $\\alpha = 0.508$ with a limit of 80.5 against 18.9. $\\phi P_{nx} = 166.6$ t, $\\phi P_{ny} = 239.2$ t, $M_p = Z_xF_y = 1869\\times2.4 = 44.86$ m.t and $\\phi_bM_p = 38.13$ m.t; $L_p = 3.91$ m $< 4.6$ m $< L_r = 15.44$ m, and with $C_b = 2.14$ the flange keeps $M_p$. $LS_1 = 1.10/(2\\times166.6) + 5.94/38.13 = 0.16$ and $LS_2 = 1.10/239.2 + (5.94/38.13)^2 = 0.03$. The roof and the wind alone would need only $S_x = 364$ cm³ — an **IPE 270** ($LS_1 = 0.62$, $LS_2 = 0.42$). The HEB 300 keeps its reserve for the crane girders on its brackets; turning it into a real crane column is the next lesson.",ar:"**المراجعات.** مدمج: الشفة 6.18، والعصب $\\alpha = 0.508$ وحده 80.5 قصاد 18.9. و $\\phi P_{nx} = 166.6$ طن، و $\\phi P_{ny} = 239.2$ طن، و $M_p = Z_xF_y = 1869\\times2.4 = 44.86$ م.طن و $\\phi_bM_p = 38.13$ م.طن؛ و $L_p = 3.91$ م $< 4.6$ م $< L_r = 15.44$ م، ومع $C_b = 2.14$ الشفة بتحافظ على $M_p$. و $LS_1 = 1.10/(2\\times166.6) + 5.94/38.13 = 0.16$ و $LS_2 = 1.10/239.2 + (5.94/38.13)^2 = 0.03$. السقف والرياح لوحدهم كانوا محتاجين $S_x = 364$ سم³ بس — **IPE 270** ($LS_1 = 0.62$، و $LS_2 = 0.42$). الـ HEB 300 محتفظ بالاحتياطي بتاعه لكمرات الونش اللي على كوابيله؛ وتحويله لعمود ونش بجد هو الدرس الجاي."}},{t:"lab",lab:"buckling",height:480,props:{preset:"bcWorkshop",missions:$,defaultTab:"steps"},caption:{en:"Your workshop column in the N + M mode: HEB 300, the curved wind diagram, the crane girder as a strut at 4.6 m.",ar:"عمود ورشتك في وضع N + M: HEB 300، ومنحنى الرياح المنحني، وكمرة الونش كستراتة عند 4.6 م."}},{t:"widget",w:"building",props:{focus:"WC-1-L",tags:["ws-columns","ws-trusses","ws-bracing","ws-crane","wind-check","ws-col-kl","ws-beamcol"]}},{t:"quiz",q:{kind:"num",q:{en:"Your column: P_u/φP_nx = 0.0066 and M_u/φbM_p = 5.94/38.13. LS₁?",ar:"عمودك: P_u/φP_nx = 0.0066 و M_u/φbM_p = 5.94/38.13. قيمة LS₁؟"},answer:.159,tol:.01,explain:{en:"Below 0.2: $0.0066/2 + 5.94/38.13 = 0.003 + 0.156 = 0.159$.",ar:"تحت 0.2: $0.0066/2 + 5.94/38.13 = 0.003 + 0.156 = 0.159$."}}}]}],quiz:[{kind:"num",q:{en:"M_ux = 20 m.t, St 52 (F_y = 3.6 t/cm²), factor 0.8. The pre-sizing S_x (cm³)?",ar:"M_ux = 20 م.طن، حديد 52 (F_y = 3.6 طن/سم²)، والمعامل 0.8. S_x لأول مقاس (سم³)؟"},answer:817,tol:.003,unit:"cm³",explain:{en:"$2000/(0.8\\times0.85\\times3.6) = 2000/2.448 = 817$ cm³.",ar:"$2000/(0.8\\times0.85\\times3.6) = 2000/2.448 = 817$ سم³."}},{kind:"mcq",q:{en:"Which limit state is the flexural–torsional one, where the column buckles sideways and twists together with its compression flange?",ar:"أنهي حالة حدية هي الانحنائية–الالتوائية، اللي فيها العمود بينبعج جانبيًا ويلف هو والشفة المضغوطة بتاعته؟"},options:[{en:"LS₂ — out of plane, with P_ny and M_nx2",ar:"LS₂ — خارج المستوى، بـ P_ny و M_nx2"},{en:"LS₁ — in plane, with P_nx",ar:"LS₁ — داخل المستوى، بـ P_nx"},{en:"neither: LTB is checked separately",ar:"ولا واحدة: الانبعاج الجانبي بيتراجع لوحده"}],answer:0,explain:{en:"Out of plane the column buckles sideways and twists: P_ny and the LTB moment M_nx2 go together in LS₂, the flexural–torsional limit state. M_nx2 is simply the LTB-reduced M_nx — the same value is used in LS₁ too.",ar:"خارج المستوى العمود بينبعج جانبيًا ويلف: P_ny وعزم الانبعاج الجانبي M_nx2 بيروحوا مع بعض في LS₂، الحالة الحدية الانحنائية–الالتوائية. و M_nx2 هو ببساطة M_nx بعد الانبعاج الجانبي — ونفس القيمة بتتاخد في LS₁ كمان."}},{kind:"num",q:{en:"P_u/φP_nx = 0.12, M_ux/φbM_nx = 0.70. LS₁?",ar:"P_u/φP_nx = 0.12، و M_ux/φbM_nx = 0.70. LS₁؟"},answer:.76,tol:.003,explain:{en:"Below 0.2: $0.12/2 + 0.70 = 0.76$.",ar:"تحت 0.2: $0.12/2 + 0.70 = 0.76$."}},{kind:"num",q:{en:"A braced column: C_m = 0.6, P_u = 40 t, P_e1 = 200 t. B₁?",ar:"عمود متربط: C_m = 0.6، و P_u = 40 طن، و P_e1 = 200 طن. B₁؟"},answer:1,tol:.003,explain:{en:"$0.6/(1 - 0.2) = 0.75 < 1$, so $B_1 = 1.0$ — the bulge does not increase the end moment.",ar:"$0.6/(1 - 0.2) = 0.75 < 1$، يبقى $B_1 = 1.0$ — التقوّس مش بيزوّد عزم الطرف."}},{kind:"num",q:{en:"ΣP_u = 300 t, first-order drift Δ_oh = 2 cm under ΣH = 10 t, storey height 6 m. B₂?",ar:"ΣP_u = 300 طن، والإزاحة من الدرجة الأولى Δ_oh = 2 سم تحت ΣH = 10 طن، وارتفاع الدور 6 م. B₂؟"},answer:1.111,tol:.003,explain:{en:"$300\\times2/(10\\times600) = 0.1$, $B_2 = 1/0.9 = 1.111$.",ar:"$300\\times2/(10\\times600) = 0.1$، و $B_2 = 1/0.9 = 1.111$."}},{kind:"num",q:{en:"A segment braced at both ends, straight diagram, α = −0.4. C_b?",ar:"جزء متثبت من طرفيه، منحنى مستقيم، و α = −0.4. C_b؟"},answer:1.378,tol:.003,explain:{en:"$1.75 - 1.05\\times0.4 + 0.3\\times0.16 = 1.75 - 0.42 + 0.048 = 1.378$.",ar:"$1.75 - 1.05\\times0.4 + 0.3\\times0.16 = 1.75 - 0.42 + 0.048 = 1.378$."}},{kind:"num",q:{en:"P_u = 20 t on a web h_w = 30 cm, t_w = 0.8 cm, F_y = 2.4 t/cm². α?",ar:"P_u = 20 طن على عصب h_w = 30 سم، و t_w = 0.8 سم، و F_y = 2.4 طن/سم². α؟"},answer:.674,tol:.003,explain:{en:"$h_wt_wF_y = 57.6$ t; $\\alpha = \\tfrac{1}{2}(20/57.6 + 1) = 0.674$.",ar:"$h_wt_wF_y = 57.6$ طن؛ و $\\alpha = \\tfrac{1}{2}(20/57.6 + 1) = 0.674$."}},{kind:"num",q:{en:"A 6 m column, fixed base; the moment reverses 4 m above the base. L_u for the upper section 1-1 (m)?",ar:"عمود 6 م قاعدته ثابتة؛ العزم بيعكس إشارته على ارتفاع 4 م من القاعدة. L_u للقطاع العلوي 1-1 (م)؟"},answer:2,tol:.003,unit:"m",explain:{en:"$L_u = h - a = 6 - 4 = 2$ m (and 4 m for the section at the base). This is the compressed length $L_1$ of the inner flange; in the column of a fixed-base trussed frame one value is then used for the whole column, the larger of $L_1$ and $L_{u,out}$: $\\max(2,\\ 4) = 4$ m.",ar:"$L_u = h - a = 6 - 4 = 2$ م (و 4 م للقطاع عند القاعدة). ده الطول المضغوط $L_1$ من الشفة الداخلية؛ وفي عمود إطار بجمالون ركائزه ثابتة بتتاخد بعد كده قيمة واحدة للعمود كله، الأكبر من $L_1$ و $L_{u,out}$: $\\max(2,\\ 4) = 4$ م."}}]};export{i as default};
